/* DAWAH X — ahmad, অধ্যায় 94 · খণ্ড 94 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][94]=[[18601,18601,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَاهُ رَجُلٌ بِصَدَقَتِهِ قَالَ اللَّهُمَّ صَلِّ عَلَى آلِ فُلَانٍ قَالَ فَأَتَاهُ أَبِي بِصَدَقَتِهِ فَقَالَ اللَّهُمَّ صَلِّ عَلَى آلِ ‏ ‏أَبِي أَوْفَى ‏","","",""],[18602,18602,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْهَجَرِيُّ ‏ ‏قَالَ ‏ ‏خَرَجْتُ فِي جِنَازَةِ ‏ ‏بِنْتِ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏وَهُوَ عَلَى بَغْلَةٍ لَهُ حَوَّاءَ ‏ ‏يَعْنِي سَوْدَاءَ ‏ ‏قَالَ فَجَعَلَ النِّسَاءُ يَقُلْنَ لِقَائِدِهِ قَدِّمْهُ أَمَامَ الْجِنَازَةِ فَفَعَلَ قَالَ ‏ ‏فَسَمِعْتُهُ ‏ ‏يَقُولُ لَهُ أَيْنَ الْجِنَازَةُ قَالَ فَقَالَ خَلْفَكَ قَالَ فَفَعَلَ ذَلِكَ مَرَّةً ‏ ‏أَوْ مَرَّتَيْنِ ‏ ‏ثُمَّ قَالَ أَلَمْ أَنْهَكَ أَنْ تُقَدِّمَنِي أَمَامَ الْجِنَازَةِ قَالَ فَسَمِعَ امْرَأَةً ‏ ‏تَلْتَدِمُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏تَرْثِي ‏ ‏فَقَالَ ‏ ‏مَهْ ‏ ‏أَلَمْ أَنْهَكُنَّ عَنْ هَذَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْهَى عَنْ ‏ ‏الْمَرَاثِي ‏ ‏لِتُفِضْ ‏ ‏إِحْدَاكُنَّ مِنْ عَبْرَتِهَا مَا شَاءَتْ فَلَمَّا وُضِعَتْ الْجِنَازَةُ تَقَدَّمَ فَكَبَّرَ عَلَيْهَا أَرْبَعَ تَكْبِيرَاتٍ ثُمَّ قَامَ ‏ ‏هُنَيْهَةً ‏ ‏فَسَبَّحَ بِهِ بَعْضُ الْقَوْمِ ‏ ‏فَانْفَتَلَ ‏ ‏فَقَالَ أَكُنْتُمْ تَرَوْنَ أَنِّي أُكَبِّرُ الْخَامِسَةَ قَالُوا نَعَمْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا كَبَّرَ الرَّابِعَةَ قَامَ ‏ ‏هُنَيَّةً ‏ ‏فَلَمَّا وُضِعَتْ الْجِنَازَةُ جَلَسَ وَجَلَسْنَا إِلَيْهِ فَسُئِلَ عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ فَقَالَ تَلَقَّانَا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏حُمُرٌ أَهْلِيَّةٌ خَارِجًا مِنْ الْقَرْيَةِ فَوَقَعَ النَّاسُ فِيهَا فَذَبَحُوهَا فَإِنَّ الْقُدُورَ لَتَغْلِي بِبَعْضِهَا إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْرِيقُوهَا ‏ ‏فَأَهْرَقْنَاهَا ‏ ‏وَرَأَيْتُ عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏مِطْرَفًا ‏ ‏مِنْ ‏ ‏خَزٍّ ‏ ‏أَخْضَرَ ‏","","",""],[18603,18603,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ يَعْنِي الصَّوَّافَ بْنَ أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِنَا فَيَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَسُورَتَيْنِ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا وَكَانَ يُطَوِّلُ فِي الرَّكْعَةِ الْأُولَى مِنْ الظُّهْرِ وَيُقَصِّرُ فِي الثَّانِيَةِ وَكَذَا فِي الصُّبْحِ ‏","","",""],[18604,18604,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَتَنَفَّسْ فِي الْإِنَاءِ وَإِذَا دَخَلَ الْخَلَاءَ فَلَا يَتَمَسَّحْ بِيَمِينِهِ وَإِذَا بَالَ فَلَا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ ‏","","",""],[18605,18605,"","","‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي طَلْحَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلَا يَأْكُلْ بِشِمَالِهِ وَإِذَا شَرِبَ فَلَا يَشْرَبْ بِشِمَالِهِ وَإِذَا أَخَذَ فَلَا يَأْخُذْ بِشِمَالِهِ وَإِذَا أَعْطَى فَلَا يُعْطِي بِشِمَالِهِ ‏","","",""],[18606,18606,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْقُرَظِيِّ ‏ ‏قَالَ ‏ ‏عُرِضْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏قُرَيْظَةَ ‏ ‏فَشَكُّوا فِيَّ ‏ ‏فَأَمَرَ بِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَنْظُرُوا إِلَيَّ هَلْ ‏ ‏أَنْبَتُّ ‏ ‏بَعْدُ فَنَظَرُوا فَلَمْ يَجِدُونِي ‏ ‏أَنْبَتُّ ‏ ‏فَخَلَّى عَنِّي وَأَلْحَقَنِي ‏ ‏بِالسَّبْيِ ‏","","",""],[18607,18607,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَطِيَّةَ ‏ ‏يَقُولُ ‏ ‏كُنْتُ يَوْمَ حَكَمَ ‏ ‏سَعْدٌ ‏ ‏فِيهِمْ غُلَامًا فَلَمْ يَجِدُونِي ‏ ‏أَنْبَتُّ ‏ ‏فَهَا أَنَا ذَا بَيْنَ أَظْهُرِكُمْ ‏","","",""],[18608,18608,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ بْنُ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏وَقَدْ سَمِعْتُهُ مِنْ ‏ ‏عُقْبَةَ ‏ ‏وَلَكِنِّي لِحَدِيثِ ‏ ‏عُبَيْدٍ ‏ ‏أَحْفَظُ ‏ ‏قَالَ ‏ ‏تَزَوَّجْتُ ‏ ‏امْرَأَةً ‏ ‏فَجَاءَتْنَا امْرَأَةٌ سَوْدَاءُ فَقَالَتْ إِنِّي قَدْ أَرْضَعْتُكُمَا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي تَزَوَّجْتُ فُلَانَةَ ابْنَةَ فُلَانٍ فَجَاءَتْنَا امْرَأَةٌ سَوْدَاءُ فَقَالَتْ إِنِّي قَدْ أَرْضَعْتُكُمَا وَهِيَ كَاذِبَةٌ فَأَعْرَضَ عَنِّي فَأَتَيْتُهُ مِنْ قِبَلِ وَجْهِهِ فَقُلْتُ إِنَّهَا كَاذِبَةٌ فَقَالَ فَكَيْفَ بِهَا وَقَدْ زَعَمَتْ أَنَّهَا قَدْ أَرْضَعَتْكُمَا دَعْهَا عَنْكَ ‏","","",""],[18609,18609,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏تَزَوَّجْتُ ‏ ‏ابْنَةَ أَبِي إِهَابٍ ‏ ‏فَجَاءَتْ امْرَأَةٌ سَوْدَاءُ فَذَكَرَتْ أَنَّهَا أَرْضَعَتْنَا فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُمْتُ بَيْنَ يَدَيْهِ فَكَلَّمْتُهُ فَأَعْرَضَ عَنِّي فَقُمْتُ عَنْ يَمِينِهِ فَأَعْرَضَ عَنِّي فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا هِيَ سَوْدَاءُ قَالَ وَكَيْفَ وَقَدْ قِيلَ ‏","","",""],[18610,18610,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقْبَةُ بْنُ الْحَارِثِ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنُّعَيْمَانِ ‏ ‏قَدْ شَرِبَ الْخَمْرَ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ فِي الْبَيْتِ فَضَرَبُوهُ بِالْأَيْدِي وَالْجَرِيدِ وَالنِّعَالِ قَالَ وَكُنْتُ فِيمَنْ ضَرَبَهُ ‏","","",""],[18611,18611,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعِيدِ بْنِ أَبِي حُسَيْنٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ فَلَمَّا سَلَّمَ قَامَ سَرِيعًا فَدَخَلَ عَلَى بَعْضِ نِسَائِهِ ثُمَّ خَرَجَ وَرَأَى مَا فِي وُجُوهِ الْقَوْمِ مِنْ ‏ ‏تَعَاجُبِهِمْ لِسُرْعَتِهِ قَالَ ‏ ‏ذَكَرْتُ وَأَنَا فِي الصَّلَاةِ ‏ ‏تِبْرًا ‏ ‏عِنْدَنَا فَكَرِهْتُ أَنْ يُمْسِيَ ‏ ‏أَوْ يَبِيتَ ‏ ‏عِنْدَنَا فَأَمَرْتُ بِقَسْمِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ صَلَّى الْعَصْرَ فَذَكَرَ مَعْنَاهُ ‏","","",""],[18612,18612,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَجِيحٍ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏حَاصَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِصْنَ ‏ ‏الطَّائِفِ ‏ ‏أَوْ قَصْرَ ‏ ‏الطَّائِفِ ‏ ‏فَقَالَ ‏ ‏مَنْ بَلَغَ بِسَهْمٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَلَهُ دَرَجَةٌ فِي الْجَنَّةِ فَبَلَغْتُ يَوْمَئِذٍ سِتَّةَ عَشَرَ سَهْمًا وَمَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَهُوَ لَهُ ‏ ‏عِدْلُ ‏ ‏مُحَرَّرٍ وَمَنْ أَصَابَهُ شَيْبٌ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَهُوَ لَهُ نُورٌ يَوْمَ الْقِيَامَةِ وَأَيُّمَا رَجُلٍ أَعْتَقَ رَجُلًا مُسْلِمًا جَعَلَ اللَّهُ عَزَّ وَجَلَّ وِقَاءَ كُلِّ عَظْمٍ مِنْ عِظَامِهِ عَظْمًا مِنْ عِظَامِ مُحَرِّرِهِ مِنْ النَّارِ وَأَيُّمَا امْرَأَةٍ مُسْلِمَةٍ أَعْتَقَتْ امْرَأَةً مُسْلِمَةً فَإِنَّ اللَّهَ عَزَّ وَجَلَّ جَاعِلٌ وِقَاءَ كُلِّ عَظْمٍ مِنْ عِظَامِهَا عَظْمًا مِنْ عِظَامِ مُحَرِّرِهَا مِنْ النَّارِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ الْغَطَفَانِيِّ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَجِيحٍ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏حَاصَرْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِصْنَ ‏ ‏الطَّائِفِ ‏ ‏فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ فَبَلَغَهُ فَلَهُ دَرَجَةٌ فِي الْجَنَّةِ فَقَالَ رَجُلٌ يَا نَبِيَّ اللَّهِ إِنْ رَمَيْتُ فَبَلَغْتُ فَلِي دَرَجَةٌ فِي الْجَنَّةِ قَالَ فَرَمَى فَبَلَغَ قَالَ فَبَلَغْتُ يَوْمَئِذٍ سِتَّةَ عَشَرَ سَهْمًا فَذَكَرَ مَعْنَاهُ ‏","","",""],[18613,18613,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ حَدِيدٍ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏صَخْرٍ الْغَامِدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏ ‏قَالَ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَعَثَ سَرِيَّةً بَعَثَهَا أَوَّلَ النَّهَارِ ‏ ‏وَكَانَ ‏ ‏صَخْرٌ ‏ ‏رَجُلًا تَاجِرًا فَكَانَ ‏ ‏لَا يَبْعَثُ غِلْمَانَهُ إِلَّا مِنْ أَوَّلِ النَّهَارِ فَكَثُرَ مَالُهُ حَتَّى لَا يَدْرِيَ أَيْنَ يَضَعُ مَالَهُ ‏","","",""],[18614,18614,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سُفْيَانَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا ‏ ‏قَالَ يَا رَسُولَ اللَّهِ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مُرْنِي فِي الْإِسْلَامِ بِأَمْرٍ لَا أَسْأَلُ عَنْهُ أَحَدًا بَعْدَكَ قَالَ قُلْ آمَنْتُ بِاللَّهِ ثُمَّ اسْتَقِمْ قَالَ قُلْتُ فَمَا ‏ ‏أَتَّقِي ‏ ‏فَأَوْمَأَ ‏ ‏إِلَى لِسَانِهِ ‏","","",""],[18615,18615,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ جَابِرٍ الْحُدَّانِيِّ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْخٌ كَبِيرٌ ‏ ‏يَدَّعِمُ ‏ ‏عَلَى عَصًا لَهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي ‏ ‏غَدَرَاتٍ ‏ ‏وَفَجَرَاتٍ ‏ ‏فَهَلْ يُغْفَرُ لِي قَالَ ‏ ‏أَلَسْتَ تَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ بَلَى وَأَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ قَالَ قَدْ غُفِرَ لَكَ ‏ ‏غَدَرَاتُكَ ‏ ‏وَفَجَرَاتُكَ ‏","","",""],[18616,18616,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ وَهُوَ الرَّحَبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِعُكَاظٍ ‏ ‏فَقُلْتُ مَنْ تَبِعَكَ عَلَى هَذَا الْأَمْرِ فَقَالَ حُرٌّ وَعَبْدٌ وَمَعَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَبِلَالٌ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏فَقَالَ لِي ارْجِعْ حَتَّى يُمَكِّنَ اللَّهُ عَزَّ وَجَلَّ لِرَسُولِهِ فَأَتَيْتُهُ بَعْدُ فَقُلْتُ يَا رَسُولَ اللَّهِ جَعَلَنِي اللَّهُ فِدَاءَكَ شَيْئًا تَعْلَمُهُ وَأَجْهَلُهُ لَا يَضُرُّكَ وَيَنْفَعُنِي اللَّهُ عَزَّ وَجَلَّ بِهِ هَلْ مِنْ سَاعَةٍ أَفْضَلُ مِنْ سَاعَةٍ وَهَلْ مِنْ سَاعَةٍ ‏ ‏يُتَّقَى فِيهَا فَقَالَ لَقَدْ سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يَتَدَلَّى فِي جَوْفِ اللَّيْلِ فَيَغْفِرُ إِلَّا مَا كَانَ مِنْ الشِّرْكِ وَالْبَغْيِ فَالصَّلَاةُ مَشْهُودَةٌ ‏ ‏مَحْضُورَةٌ ‏ ‏فَصَلِّ حَتَّى تَطْلُعَ الشَّمْسُ فَإِذَا طَلَعَتْ فَأَقْصِرْ عَنْ الصَّلَاةِ فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَهِيَ صَلَاةُ الْكُفَّارِ حَتَّى تَرْتَفِعَ فَإِذَا ‏ ‏اسْتَقَلَّتْ ‏ ‏الشَّمْسُ فَصَلِّ فَإِنَّ الصَّلَاةَ ‏ ‏مَحْضُورَةٌ ‏ ‏مَشْهُودَةٌ حَتَّى يَعْتَدِلَ النَّهَارُ فَإِذَا اعْتَدَلَ النَّهَارُ فَأَقْصِرْ عَنْ الصَّلَاةِ فَإِنَّهَا سَاعَةٌ ‏ ‏تُسَجَّرُ ‏ ‏فِيهَا جَهَنَّمُ حَتَّى ‏ ‏يَفِيءَ ‏ ‏الْفَيْءُ ‏ ‏فَإِذَا ‏ ‏فَاءَ ‏ ‏الْفَيْءُ ‏ ‏فَصَلِّ فَإِنَّ الصَّلَاةَ ‏ ‏مَحْضُورَةٌ ‏ ‏مَشْهُودَةٌ حَتَّى تَدَلَّى الشَّمْسُ لِلْغُرُوبِ فَإِذَا تَدَلَّتْ فَأَقْصِرْ عَنْ الصَّلَاةِ حَتَّى تَغِيبَ الشَّمْسُ فَإِنَّهَا تَغِيبُ عَلَى قَرْنَيْ شَيْطَانٍ وَهِيَ صَلَاةُ الْكُفَّارِ ‏","","",""],[18617,18617,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ‏ ‏مَنْ تَابَعَكَ عَلَى أَمْرِكَ هَذَا قَالَ حُرٌّ وَعَبْدٌ ‏ ‏يَعْنِي ‏ ‏أَبَا بَكْرٍ ‏ ‏وَبِلَالًا ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏وَكَانَ ‏ ‏عَمْرٌو ‏ ‏يَقُولُ ‏ ‏بَعْدَ ذَلِكَ ‏ ‏فَلَقَدْ رَأَيْتُنِي وَإِنِّي ‏ ‏لَرُبُعُ ‏ ‏الْإِسْلَامِ ‏","","",""],[18618,18618,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مَنْ تَبِعَكَ عَلَى هَذَا الْأَمْرِ قَالَ حُرٌّ وَعَبْدٌ قُلْتُ مَا الْإِسْلَامُ قَالَ طِيبُ الْكَلَامِ وَإِطْعَامُ الطَّعَامِ قُلْتُ مَا الْإِيمَانُ قَالَ الصَّبْرُ وَالسَّمَاحَةُ قَالَ قُلْتُ أَيُّ الْإِسْلَامِ أَفْضَلُ قَالَ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ قَالَ قُلْتُ أَيُّ الْإِيمَانِ أَفْضَلُ قَالَ خُلُقٌ حَسَنٌ قَالَ قُلْتُ أَيُّ الصَّلَاةِ أَفْضَلُ قَالَ طُولُ ‏ ‏الْقُنُوتِ ‏ ‏قَالَ قُلْتُ أَيُّ الْهِجْرَةِ أَفْضَلُ قَالَ أَنْ تَهْجُرَ مَا كَرِهَ رَبُّكَ عَزَّ وَجَلَّ قَالَ قُلْتُ فَأَيُّ الْجِهَادِ أَفْضَلُ قَالَ مَنْ ‏ ‏عُقِرَ ‏ ‏جَوَادُهُ ‏ ‏وَأُهْرِيقَ ‏ ‏دَمُهُ قَالَ قُلْتُ أَيُّ السَّاعَاتِ أَفْضَلُ قَالَ جَوْفُ اللَّيْلِ الْآخِرُ ثُمَّ الصَّلَاةُ مَكْتُوبَةٌ مَشْهُودَةٌ حَتَّى يَطْلُعَ الْفَجْرُ فَإِذَا طَلَعَ الْفَجْرُ فَلَا صَلَاةَ إِلَّا الرَّكْعَتَيْنِ حَتَّى تُصَلِّيَ الْفَجْرَ فَإِذَا صَلَّيْتَ صَلَاةَ الصُّبْحِ فَأَمْسِكْ عَنْ الصَّلَاةِ حَتَّى تَطْلُعَ الشَّمْسُ فَإِذَا طَلَعَتْ الشَّمْسُ فَإِنَّهَا تَطْلُعُ فِي قَرْنَيْ شَيْطَانٍ وَإِنَّ الْكُفَّارَ يُصَلُّونَ لَهَا فَأَمْسِكْ عَنْ الصَّلَاةِ حَتَّى تَرْتَفِعَ فَإِذَا ارْتَفَعَتْ فَالصَّلَاةُ مَكْتُوبَةٌ مَشْهُودَةٌ حَتَّى يَقُومَ الظِّلُّ قِيَامَ الرُّمْحِ فَإِذَا كَانَ كَذَلِكَ فَأَمْسِكْ عَنْ الصَّلَاةِ حَتَّى تَمِيلَ فَإِذَا مَالَتْ فَالصَّلَاةُ مَكْتُوبَةٌ مَشْهُودَةٌ حَتَّى تَغْرُبَ الشَّمْسُ فَإِذَا كَانَ عِنْدَ غُرُوبِهَا فَأَمْسِكْ عَنْ الصَّلَاةِ فَإِنَّهَا تَغْرُبُ ‏ ‏أَوْ تَغِيبُ ‏ ‏فِي قَرْنَيْ شَيْطَانٍ وَإِنَّ الْكُفَّارَ يُصَلُّونَ لَهَا ‏","","",""],[18619,18619,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْفَيْضِ ‏ ‏عَنْ ‏ ‏سُلَيْمِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏كَانَ بَيْنَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَبَيْنَ قَوْمٍ مِنْ ‏ ‏الرُّومِ ‏ ‏عَهْدٌ فَخَرَجَ ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ فَجَعَلَ يَسِيرُ فِي أَرْضِهِمْ حَتَّى يَنْقُضُوا فَيُغِيرَ عَلَيْهِمْ فَإِذَا رَجُلٌ يُنَادِي فِي نَاحِيَةِ النَّاسِ وَفَاءٌ لَا غَدْرٌ فَإِذَا هُوَ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ بَيْنَهُ وَبَيْنَ قَوْمٍ عَهْدٌ فَلَا يَشِدَّ عُقْدَةً وَلَا يَحُلَّ حَتَّى يَمْضِيَ أَمَدُهَا أَوْ يَنْبِذَ إِلَيْهِمْ عَلَى سَوَاءٍ ‏","","",""],[18620,18620,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ حَدِّثْنَا حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيهِ انْتِقَاصٌ وَلَا وَهْمٌ قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏مَنْ وُلِدَ لَهُ ثَلَاثَةُ أَوْلَادٍ فِي الْإِسْلَامِ فَمَاتُوا قَبْلَ أَنْ يَبْلُغُوا ‏ ‏الْحِنْثَ ‏ ‏أَدْخَلَهُ اللَّهُ عَزَّ وَجَلَّ الْجَنَّةَ بِرَحْمَتِهِ إِيَّاهُمْ وَمَنْ ‏ ‏شَابَ ‏ ‏شَيْبَةً ‏ ‏فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ وَمَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ بَلَغَ بِهِ الْعَدُوَّ أَصَابَ أَوْ أَخْطَأَ كَانَ لَهُ كَعِدْلِ رَقَبَةٍ وَمَنْ أَعْتَقَ رَقَبَةً مُؤْمِنَةً أَعْتَقَ اللَّهُ بِكُلِّ عُضْوٍ مِنْهَا عُضْوًا مِنْهُ مِنْ النَّارِ وَمَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَإِنَّ لِلْجَنَّةِ ثَمَانِيَةَ أَبْوَابٍ يُدْخِلُهُ اللَّهُ عَزَّ وَجَلَّ مِنْ أَيِّ بَابٍ شَاءَ مِنْهَا الْجَنَّةَ ‏","","",""],[18621,18621,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو ظَبْيَةَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏شُرَحْبِيلَ بْنَ السِّمْطِ ‏ ‏دَعَا ‏ ‏عَمْرَو بْنَ عَبَسَةَ السُّلَمِيَّ ‏ ‏فَقَالَ يَا ‏ ‏ابْنَ عَبَسَةَ ‏ ‏هَلْ أَنْتَ مُحَدِّثِي حَدِيثًا سَمِعْتَهُ أَنْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيهِ تَزَيُّدٌ وَلَا كَذِبٌ وَلَا تُحَدِّثْنِيهِ عَنْ آخَرَ سَمِعَهُ مِنْهُ غَيْرِكَ قَالَ نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ قَدْ ‏ ‏حَقَّتْ مَحَبَّتِي لِلَّذِينَ يَتَحَابُّونَ مِنْ أَجْلِي وَحَقَّتْ مَحَبَّتِي لِلَّذِينَ يَتَصَافُّونَ مِنْ أَجْلِي وَحَقَّتْ مَحَبَّتِي لِلَّذِينَ يَتَزَاوَرُونَ مِنْ أَجْلِي وَحَقَّتْ مَحَبَّتِي لِلَّذِينَ ‏ ‏يَتَبَاذَلُونَ مِنْ أَجْلِي وَحَقَّتْ مَحَبَّتِي لِلَّذِينَ يَتَنَاصَرُونَ مِنْ أَجْلِي ‏","","",""],[18622,18622,"","","‏ ‏و قَالَ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا رَجُلٍ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَبَلَغَ مُخْطِئًا أَوْ مُصِيبًا فَلَهُ مِنْ الْأَجْرِ كَرَقَبَةٍ يُعْتِقُهَا مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏ ‏وَأَيُّمَا رَجُلٍ ‏ ‏شَابَ ‏ ‏شَيْبَةً ‏ ‏فِي سَبِيلِ اللَّهِ فَهِيَ لَهُ نُورٌ وَأَيُّمَا رَجُلٍ مُسْلِمٍ أَعْتَقَ رَجُلًا مُسْلِمًا فَكُلُّ عُضْوٍ مِنْ الْمُعْتَقِ بِعُضْوٍ مِنْ الْمُعْتِقِ فِدَاءٌ لَهُ مِنْ النَّارِ وَأَيُّمَا امْرَأَةٍ مُسْلِمَةٍ أَعْتَقَتْ امْرَأَةً مُسْلِمَةً فَكُلُّ عُضْوٍ مِنْ الْمُعْتَقَةِ بِعُضْوٍ مِنْ الْمُعْتِقَةِ فِدَاءٌ لَهَا مِنْ النَّارِ وَأَيُّمَا رَجُلٍ مُسْلِمٍ قَدَّمَ لِلَّهِ عَزَّ وَجَلَّ مِنْ صُلْبِهِ ثَلَاثَةً لَمْ يَبْلُغُوا ‏ ‏الْحِنْثَ ‏ ‏أَوْ امْرَأَةٍ فَهُمْ لَهُ ‏ ‏سُتْرَةٌ ‏ ‏مِنْ النَّارِ وَأَيُّمَا رَجُلٍ قَامَ إِلَى وَضُوءٍ يُرِيدُ الصَّلَاةَ فَأَحْصَى الْوَضُوءَ إِلَى أَمَاكِنِهِ سَلِمَ مِنْ كُلِّ ذَنْبٍ ‏ ‏أَوْ خَطِيئَةٍ ‏ ‏لَهُ فَإِنْ قَامَ إِلَى الصَّلَاةِ رَفَعَهُ اللَّهُ عَزَّ وَجَلَّ بِهَا دَرَجَةً وَإِنْ قَعَدَ قَعَدَ سَالِمًا فَقَالَ ‏ ‏شُرَحْبِيلُ بْنُ السِّمْطِ ‏ ‏آنْتَ سَمِعْتَ هَذَا الْحَدِيثَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏ابْنَ عَبَسَةَ ‏ ‏قَالَ نَعَمْ وَالَّذِي لَا إِلَهَ إِلَّا هُوَ لَوْ أَنِّي لَمْ أَسْمَعْ هَذَا الْحَدِيثَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرَ مَرَّةٍ أَوْ مَرَّتَيْنِ أَوْ ثَلَاثٍ أَوْ أَرْبَعٍ أَوْ خَمْسٍ أَوْ سِتٍّ أَوْ سَبْعٍ فَانْتَهَى عِنْدَ سَبْعٍ مَا حَلَفْتُ ‏ ‏يَعْنِي مَا بَالَيْتُ ‏ ‏أَنْ لَا أُحَدِّثَ بِهِ أَحَدًا مِنْ النَّاسِ وَلَكِنِّي وَاللَّهِ مَا أَدْرِي عَدَدَ مَا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18623,18623,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏أَنَّهُ حَدَّثَهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ بَنَى لِلَّهِ مَسْجِدًا لِيُذْكَرَ اللَّهُ عَزَّ وَجَلَّ فِيهِ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ وَمَنْ أَعْتَقَ نَفْسًا مُسْلِمَةً كَانَتْ فِدْيَتَهُ مِنْ جَهَنَّمَ وَمَنْ ‏ ‏شَابَ ‏ ‏شَيْبَةً ‏ ‏فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ ‏","","",""],[18624,18624,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ ثَنَا ‏ ‏حَرِيزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ عَامِرٍ ‏ ‏حَدِيثَ ‏ ‏شُرَحْبِيلَ بْنِ السِّمْطِ ‏ ‏حِينَ قَالَ ‏ ‏لِعَمْرِو بْنِ عَبَسَةَ ‏ ‏حَدِّثْنَا حَدِيثًا لَيْسَ فِيهِ ‏ ‏تَزَيُّدٌ وَلَا نُقْصَانٌ ‏ ‏فَقَالَ ‏ ‏عَمْرٌو ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً مُسْلِمَةً كَانَتْ فِكَاكَهُ مِنْ النَّارِ عُضْوًا بِعُضْوٍ ‏","","",""],[18625,18625,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُبَيْدٍ أَبُو دَوْسٍ الْيَحْصَبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَائِذٍ الثُّمَالِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرُّ قَبِيلَتَيْنِ فِي ‏ ‏الْعَرَبِ ‏ ‏نَجْرَانُ ‏ ‏وَبَنُو تَغْلِبَ ‏","","",""],[18626,18626,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏حَدَّثَنِي ‏ ‏شُرَحْبِيلُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ مَوْهَبٍ الْأَمْلُوكِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏السَّكُونِ ‏ ‏وَالسَّكَاسِكِ ‏ ‏وَعَلَى ‏ ‏خَوْلَانَ الْعَالِيَةِ ‏ ‏وَعَلَى ‏ ‏الْأَمْلُوكِ ‏ ‏أَمْلُوكِ رَدْمَانِ ‏","","",""],[18627,18627,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ السِّمْطِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَاتَلَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏ ‏فُوَاقَ ‏ ‏نَاقَةٍ حَرَّمَ اللَّهُ عَلَى وَجْهِهِ النَّارَ ‏","","",""],[18628,18628,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنِي ‏ ‏شُرَيْحُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَائِذٍ الْأَزْدِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْرِضُ يَوْمًا خَيْلًا وَعِنْدَهُ ‏ ‏عُيَيْنَةُ بْنُ حِصْنِ بْنِ بَدْرٍ الْفَزَارِيُّ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏أَفْرَسُ ‏ ‏بِالْخَيْلِ مِنْكَ فَقَالَ ‏ ‏عُيَيْنَةُ ‏ ‏وَأَنَا ‏ ‏أَفْرَسُ ‏ ‏بِالرِّجَالِ مِنْكَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَيْفَ ذَاكَ قَالَ خَيْرُ الرِّجَالِ رِجَالٌ يَحْمِلُونَ سُيُوفَهُمْ عَلَى ‏ ‏عَوَاتِقِهِمْ ‏ ‏جَاعِلِينَ رِمَاحَهُمْ عَلَى ‏ ‏مَنَاسِجِ ‏ ‏خُيُولِهِمْ لَابِسُو ‏ ‏الْبُرُودِ ‏ ‏مِنْ أَهْلِ ‏ ‏نَجْدٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبْتَ بَلْ ‏ ‏خَيْرُ الرِّجَالِ رِجَالُ أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏وَالْإِيمَانُ ‏ ‏يَمَانٍ ‏ ‏إِلَى ‏ ‏لَخْمٍ ‏ ‏وَجُذَامَ ‏ ‏وَعَامِلَةَ ‏ ‏وَمَأْكُولُ ‏ ‏حِمْيَرَ ‏ ‏خَيْرٌ مِنْ آكِلِهَا ‏ ‏وَحَضْرَمَوْتُ ‏ ‏خَيْرٌ مِنْ ‏ ‏بَنِي الْحَارِثِ ‏ ‏وَقَبِيلَةٌ خَيْرٌ مِنْ قَبِيلَةٍ وَقَبِيلَةٌ شَرٌّ مِنْ قَبِيلَةٍ وَاللَّهِ مَا أُبَالِي أَنْ يَهْلِكَ الْحَارِثَانِ كِلَاهُمَا لَعَنَ اللَّهُ الْمُلُوكَ الْأَرْبَعَةَ ‏ ‏جَمَدَاءَ ‏ ‏وَمِخْوَسَاءَ ‏ ‏وَمِشْرَخَاءَ ‏ ‏وَأَبْضَعَةَ ‏ ‏وَأُخْتَهُمْ ‏ ‏الْعَمَرَّدَةَ ‏ ‏ثُمَّ قَالَ أَمَرَنِي رَبِّي عَزَّ وَجَلَّ أَنْ أَلْعَنَ ‏ ‏قُرَيْشًا ‏ ‏مَرَّتَيْنِ فَلَعَنْتُهُمْ وَأَمَرَنِي أَنْ أُصَلِّيَ عَلَيْهِمْ فَصَلَّيْتُ عَلَيْهِمْ مَرَّتَيْنِ ثُمَّ قَالَ ‏ ‏عُصَيَّةُ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ غَيْرَ ‏ ‏قَيْسٍ ‏ ‏وَجَعْدَةَ ‏ ‏وَعُصَيَّةَ ‏ ‏ثُمَّ قَالَ ‏ ‏لَأَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَأَخْلَاطُهُمْ مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏خَيْرٌ مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏وَتَمِيمٍ ‏ ‏وَغَطَفَانَ ‏ ‏وَهَوَازِنَ ‏ ‏عِنْدَ اللَّهِ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ ثُمَّ قَالَ شَرُّ قَبِيلَتَيْنِ فِي ‏ ‏الْعَرَبِ ‏ ‏نَجْرَانُ ‏ ‏وَبَنُو تَغْلِبَ ‏ ‏وَأَكْثَرُ الْقَبَائِلِ فِي الْجَنَّةِ ‏ ‏مَذْحِجٌ ‏ ‏وَمَأْكُولُ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏صَفْوَانُ ‏ ‏حِمْيَرَ ‏ ‏حِمْيَرَ ‏ ‏خَيْرٌ مِنْ آكِلِهَا قَالَ مَنْ مَضَى خَيْرٌ مِمَّنْ بَقِيَ ‏","","",""],[18629,18629,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى وَجَوْفُ اللَّيْلِ الْآخِرُ ‏ ‏أَجْوَبُهُ دَعْوَةً ‏ ‏قُلْتُ أَوْجَبُهُ ‏ ‏قَالَ ‏ ‏لَا بَلْ ‏ ‏أَجْوَبُهُ ‏ ‏يَعْنِي بِذَلِكَ الْإِجَابَةَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[18630,18630,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى وَجَوْفُ اللَّيْلِ الْآخِرُ أَوْجَبُهُ دَعْوَةً ‏ ‏قَالَ ‏ ‏فَقُلْتُ أَوْجَبُهُ ‏ ‏قَالَ ‏ ‏لَا وَلَكِنْ أَوْجَبُهُ ‏ ‏يَعْنِي بِذَلِكَ الْإِجَابَةَ ‏","","",""],[18631,18631,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْرِضُ خَيْلًا وَعِنْدَهُ ‏ ‏عُيَيْنَةُ بْنُ حِصْنِ بْنِ حُذَيْفَةَ بْنِ بَدْرٍ الْفَزَارِيُّ ‏ ‏فَقَالَ ‏ ‏لِعُيَيْنَةَ ‏ ‏أَنَا أَبْصَرُ بِالْخَيْلِ مِنْكَ فَقَالَ ‏ ‏عُيَيْنَةُ ‏ ‏وَأَنَا أَبْصَرُ بِالرِّجَالِ مِنْكَ قَالَ فَكَيْفَ ذَاكَ قَالَ خِيَارُ الرِّجَالِ الَّذِينَ يَضَعُونَ أَسْيَافَهُمْ عَلَى ‏ ‏عَوَاتِقِهِمْ ‏ ‏وَيَعْرِضُونَ رِمَاحَهُمْ عَلَى ‏ ‏مَنَاسِجِ ‏ ‏خُيُولِهِمْ مِنْ أَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَالَ كَذَبْتَ ‏ ‏خِيَارُ الرِّجَالِ رِجَالُ أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏وَالْإِيمَانُ ‏ ‏يَمَانٍ ‏ ‏وَأَنَا ‏ ‏يَمَانٍ ‏ ‏وَأَكْثَرُ الْقَبَائِلِ يَوْمَ الْقِيَامَةِ فِي الْجَنَّةِ ‏ ‏مَذْحِجٌ ‏ ‏وحَضْرَمَوْتُ ‏ ‏خَيْرٌ مِنْ ‏ ‏بَنِي الْحَارِثِ ‏ ‏وَمَا أُبَالِي أَنْ يَهْلِكَ الْحَيَّانِ كِلَاهُمَا فَلَا قِيلَ وَلَا مُلْكَ إِلَّا لِلَّهِ عَزَّ وَجَلَّ لَعَنَ اللَّهُ الْمُلُوكَ الْأَرْبَعَةَ ‏ ‏جَمَدَاءَ ‏ ‏وَمِشْرَخَاءَ ‏ ‏وَمِخْوَسَاءَ ‏ ‏وَأَبْضَعَةَ ‏ ‏وَأُخْتَهُمْ ‏ ‏الْعَمَرَّدَةَ ‏","","",""],[18632,18632,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ صَيْفِيٍّ الْأَنْصَارىِّ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏يَوْمِ عَاشُورَاءَ ‏ ‏فَقَالَ أَصُمْتُمْ يَوْمَكُمْ هَذَا فَقَالَ بَعْضُهُمْ نَعَمْ وَقَالَ بَعْضُهُمْ لَا قَالَ فَأَتِمُّوا بَقِيَّةَ يَوْمِكُمْ هَذَا وَأَمَرَهُمْ أَنْ يُؤْذِنُوا أَهْلَ الْعَرُوضِ أَنْ يُتِمُّوا يَوْمَهُمْ ذَلِكَ ‏","","",""],[18633,18633,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏يَزِيدَ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا وَرَدْنَا ‏ ‏الْبَقِيعَ ‏ ‏إِذَا هُوَ بِقَبْرٍ جَدِيدٍ فَسَأَلَ عَنْهُ فَقِيلَ فُلَانَةُ فَعَرَفَهَا فَقَالَ أَلَا ‏ ‏آذَنْتُمُونِي ‏ ‏بِهَا قَالُوا يَا رَسُولَ اللَّهِ كُنْتَ ‏ ‏قَائِلًا ‏ ‏صَائِمًا فَكَرِهْنَا أَنْ نُؤْذِنَكَ فَقَالَ ‏ ‏لَا تَفْعَلُوا لَا يَمُوتَنَّ فِيكُمْ مَيِّتٌ مَا كُنْتُ بَيْنَ أَظْهُرِكُمْ أَلَا ‏ ‏آذَنْتُمُونِي ‏ ‏بِهِ فَإِنَّ صَلَاتِي عَلَيْهِ لَهُ رَحْمَةٌ قَالَ ثُمَّ أَتَى الْقَبْرَ فَصَفَّنَا خَلْفَهُ وَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[18634,18634,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ يَعْنِي ابْنَ حَكِيمٍ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏يَزِيدَ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏كَانَ جَالِسًا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَصْحَابِهِ فَطَلَعَتْ جِنَازَةٌ فَلَمَّا رَآهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَارَ ‏ ‏وَثَارَ ‏ ‏أَصْحَابُهُ مَعَهُ فَلَمْ يَزَالُوا قِيَامًا حَتَّى نَفَذَتْ قَالَ وَاللَّهِ مَا أَدْرِي مِنْ تَأَذٍّ بِهَا ‏ ‏أَوْ مِنْ تَضَايُقِ ‏ ‏الْمَكَانِ وَلَا أَحْسِبُهَا إِلَّا يَهُودِيًّا ‏ ‏أَوْ يَهُودِيَّةً ‏ ‏وَمَا سَأَلْنَا عَنْ قِيَامِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18635,18635,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شَرِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الشَّرِيدِ بْنِ سُوَيْدٍ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا جَالِسٌ هَكَذَا وَقَدْ وَضَعْتُ يَدِي الْيُسْرَى خَلْفَ ظَهْرِي وَاتَّكَأْتُ عَلَى ‏ ‏أَلْيَةِ يَدِي ‏ ‏فَقَالَ أَتَقْعُدُ قَعْدَةَ الْمَغْضُوبِ عَلَيْهِمْ ‏","","",""],[18636,18636,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏الشَّرِيدِ ‏ ‏أَنَّ أُمَّهُ أَوْصَتْ أَنْ يُعْتِقُوا عَنْهَا رَقَبَةً مُؤْمِنَةً فَسَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ عِنْدِي ‏ ‏جَارِيَةٌ ‏ ‏سَوْدَاءُ ‏ ‏نُوبِيَّةٌ فَأُعْتِقُهَا عَنْهَا فَقَالَ ائْتِ بِهَا فَدَعَوْتُهَا فَجَاءَتْ فَقَالَ لَهَا ‏ ‏مَنْ رَبُّكِ قَالَتْ اللَّهُ قَالَ مَنْ أَنَا قَالَتْ أَنْتَ رَسُولُ اللَّهِ قَالَ أَعْتِقْهَا فَإِنَّهَا مُؤْمِنَةٌ ‏","","",""],[18637,18637,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏وَبْرُ بْنُ أَبِي دُلَيْلَةَ ‏ ‏شَيْخٌ مِنْ أَهْلِ ‏ ‏الطَّائِفِ ‏ ‏عَنِ ‏ ‏مُحَمَّدِ بْنِ مَيْمُونِ بْنِ مُسَيْكَةَ ‏ ‏وَأَثْنَى عَلَيْهِ خَيْرًا ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُّ ‏ ‏الْوَاجِدِ ‏ ‏يُحِلُّ عِرْضَهُ وَعُقُوبَتَهُ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏عِرْضُهُ ‏ ‏شِكَايَتُهُ وَعُقُوبَتُهُ حَبْسُهُ ‏","","",""],[18638,18638,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ بْنِ يَعْلَى بْنِ كَعْبٍ الثَّقَفِيَّ الطَّائِفِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ الشَّرِيدِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏اسْتَنْشَدَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ شِعْرِ ‏ ‏أُمَيَّةَ بْنِ أَبِي الصَّلْتِ ‏ ‏فَأَنْشَدْتُهُ فَكُلَّمَا أَنْشَدْتُهُ بَيْتًا قَالَ هِيَ حَتَّى أَنْشَدْتُهُ مِائَةَ قَافِيَةٍ فَقَالَ إِنْ كَادَ لَيُسْلِمُ ‏","","",""],[18639,18639,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الشَّرِيدِ ‏ ‏أَنَّهُ سَمِعَهُ يُخْبِرُهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ إِذَا وَجَدَ الرَّجُلَ رَاقِدًا عَلَى وَجْهِهِ لَيْسَ عَلَى ‏ ‏عَجُزِهِ ‏ ‏شَيْءٌ ‏ ‏رَكَضَهُ ‏ ‏بِرِجْلِهِ وَقَالَ ‏ ‏هِيَ أَبْغَضُ الرِّقْدَةِ إِلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18640,18640,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنِ ‏ ‏الشَّرِيدِ بْنِ سُوَيْدٍ الثَّقَفِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَارُ الدَّارِ أَحَقُّ بِالدَّارِ مِنْ غَيْرِهِ ‏","","",""],[18641,18641,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي عَاصِمِ بْنِ عُرْوَةَ بْنِ مَسْعُودٍ الثَّقَفِيُّ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ الشَّرِيدِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا شَرِبَ الرَّجُلُ فَاجْلِدُوهُ ثُمَّ إِذَا شَرِبَ فَاجْلِدُوهُ أَرْبَعَ مِرَارٍ ‏ ‏أَوْ خَمْسَ مِرَارٍ ‏ ‏ثُمَّ إِذَا شَرِبَ فَاقْتُلُوهُ ‏","","",""],[18642,18642,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الشَّرِيدِ بْنِ سُوَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَرْضٌ لَيْسَ لِأَحَدٍ فِيهَا شِرْكٌ وَلَا قَسْمٌ إِلَّا الْجِوَارُ قَالَ ‏ ‏الْجَارُ أَحَقُّ بِسَقَبِهِ مَا كَانَ ‏","","",""],[18643,18643,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏وَالْخَفَّافُ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الشَّرِيدِ بْنِ سُوَيْدٍ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏قَالَ ‏ ‏الْخَفَّافُ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَرْضٌ لَيْسَ لِأَحَدٍ فِيهَا شِرْكٌ وَلَا قَسْمٌ إِلَّا الْجِوَارُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَارُ أَحَقُّ ‏ ‏بِسَقَبِهِ ‏ ‏مَا كَانَ ‏","","",""],[18644,18644,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏أَخْبَرَنِي ‏ ‏وَبْرُ بْنُ أَبِي دُلَيْلَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ مَيْمُونِ بْنِ مُسَيْكَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الشَّرِيدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُّ ‏ ‏الْوَاجِدِ ‏ ‏يُحِلُّ عِرْضَهُ وَعُقُوبَتَهُ ‏","","",""],[18645,18645,"","","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْلَى بْنِ كَعْبٍ الطَّائِفِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَنْشَدَهُ مِنْ شِعْرِ ‏ ‏أُمَيَّةَ بْنِ أَبِي الصَّلْتِ ‏ ‏قَالَ فَأَنْشَدَهُ مِائَةَ قَافِيَةٍ فَلَمْ أُنْشِدْهُ شَيْئًا إِلَّا قَالَ إِيهِ إِيهِ حَتَّى إِذَا اسْتَفْرَغْتُ مِنْ مِائَةِ قَافِيَةٍ قَالَ كَادَ أَنْ يُسْلِمَ ‏","","",""],[18646,18646,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏يَعْقُوبَ بْنَ عَاصِمِ بْنِ عُرْوَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الشَّرِيدَ ‏ ‏يَقُولُ ‏ ‏أَشْهَدُ لَوَقَفْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَاتٍ ‏ ‏قَالَ ‏ ‏فَمَا مَسَّتْ قَدَمَاهُ الْأَرْضَ حَتَّى أَتَى ‏ ‏جَمْعًا ‏","","",""],[18647,18647,"","","‏ ‏حَدَّثَنَا ‏ ‏مُهَنَّأُ بْنُ عَبْدِ الْحَمِيدِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏كُنْيَتُهُ ‏ ‏أَبُو شِبْلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏الشَّرِيدِ ‏ ‏أَنَّ أُمَّهُ أَوْصَتْ أَنْ يُعْتَقَ عَنْهَا رَقَبَةٌ مُؤْمِنَةٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أُمِّي أَوْصَتْ أَنْ يُعْتَقَ عَنْهَا رَقَبَةٌ مُؤْمِنَةٌ وَعِنْدِي جَارِيَةٌ ‏ ‏نُوبِيَّةٌ سَوْدَاءُ فَقَالَ ادْعُ بِهَا فَجَاءَ بِهَا فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَبُّكِ قَالَتْ اللَّهُ قَالَ مَنْ أَنَا قَالَتْ أَنْتَ رَسُولُ اللَّهِ قَالَ أَعْتِقْهَا فَإِنَّهَا مُؤْمِنَةٌ ‏","","",""],[18648,18648,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَمْرَو بْنَ الشَّرِيدِ ‏ ‏يَقُولُ قَالَ ‏ ‏الشَّرِيدُ ‏ ‏كُنْتُ ‏ ‏رِدْفًا ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي ‏ ‏أَمَعَكَ مِنْ شِعْرِ ‏ ‏أُمَيَّةَ بْنِ أَبِي الصَّلْتِ ‏ ‏شَيْءٌ قُلْتُ نَعَمْ فَقَالَ أَنْشِدْنِي فَأَنْشَدْتُهُ بَيْتًا فَلَمْ يَزَلْ يَقُولُ لِي كُلَّمَا أَنْشَدْتُهُ بَيْتًا إِيهِ حَتَّى أَنْشَدْتُهُ مِائَةَ بَيْتٍ قَالَ ثُمَّ سَكَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَكَتُّ ‏","","",""],[18649,18649,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ ‏ ‏مَجْذُومٌ ‏ ‏مِنْ ‏ ‏ثَقِيفٍ ‏ ‏لِيُبَايِعَهُ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ ‏ ‏ائْتِهِ فَأَخْبِرْهُ أَنِّي قَدْ ‏ ‏بَايَعْتُهُ ‏ ‏فَلْيَرْجِعْ ‏","","",""],[18650,18650,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ أَبُو يَعْلَى الطَّائِفِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَ ثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْلَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ الشَّرِيدِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَارُ أَحَقُّ ‏ ‏بِسَقَبِهِ ‏ ‏مِنْ غَيْرِهِ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏فِي حَدِيثِهِ الْمَرْءُ أَحَقُّ ‏","","",""],[18651,18651,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ الْحَدَّادُ أَبُو عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏خَلَفٍ يَعْنِي ابْنَ مِهْرَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّرِيدَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَتَلَ عُصْفُورًا عَبَثًا ‏ ‏عَجَّ ‏ ‏إِلَى اللَّهِ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ مِنْهُ يَقُولُ يَا رَبِّ إِنَّ فُلَانًا قَتَلَنِي عَبَثًا وَلَمْ يَقْتُلْنِي لِمَنْفَعَةٍ ‏","","",""],[18652,18652,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏يَعْقُوبَ بْنَ عَاصِمِ بْنِ عُرْوَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الشَّرِيدَ ‏ ‏قَالَ ‏ ‏أَشْهَدُ ‏ ‏لَأَفَضْتُ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا مَسَّتْ قَدَمَاهُ الْأَرْضَ حَتَّى أَتَى ‏ ‏جَمْعًا ‏ ‏وَقَالَ ‏ ‏مَرَّةً لَوَقَفْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَاتٍ ‏ ‏فَمَا مَسَّتْ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَيْثُ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏وَقَفْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْلَاهُ مِنْ كِتَابِهِ ‏","","",""],[18653,18653,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَمْرَو بْنَ الشَّرِيدِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَبِعَ رَجُلًا مِنْ ‏ ‏ثَقِيفٍ ‏ ‏حَتَّى هَرْوَلَ فِي أَثَرِهِ حَتَّى أَخَذَ ثَوْبَهُ فَقَالَ ارْفَعْ ‏ ‏إِزَارَكَ ‏ ‏قَالَ فَكَشَفَ الرَّجُلُ عَنْ رُكْبَتَيْهِ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏أَحْنَفُ ‏ ‏وَتَصْطَكُّ ‏ ‏رُكْبَتَايَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ خَلْقِ اللَّهِ عَزَّ وَجَلَّ حَسَنٌ ‏ ‏قَالَ ‏ ‏وَلَمْ يُرَ ذَلِكَ الرَّجُلُ إِلَّا وَإِزَارُهُ إِلَى أَنْصَافِ سَاقَيْهِ حَتَّى مَاتَ ‏","","",""],[18654,18654,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَمْرَو بْنَ الشَّرِيدِ ‏ ‏يَقُولُ ‏ ‏بَلَغَنَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى رَجُلٍ وَهُوَ رَاقِدٌ عَلَى وَجْهِهِ فَقَالَ هَذَا أَبْغَضُ الرُّقَادِ إِلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18655,18655,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ فِي ‏ ‏وَفْدِ ثَقِيفٍ ‏ ‏رَجُلٌ ‏ ‏مَجْذُومٌ ‏ ‏فَأَرْسَلَ إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْجِعْ فَقَدْ ‏ ‏بَايَعْتُكَ ‏","","",""],[18656,18656,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عَاصِمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الشَّرِيدَ ‏ ‏يَقُولُ ‏ ‏أَبْصَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏فَأَسْرَعَ إِلَيْهِ ‏ ‏أَوْ هَرْوَلَ ‏ ‏فَقَالَ ارْفَعْ ‏ ‏إِزَارَكَ ‏ ‏وَاتَّقِ اللَّهَ قَالَ إِنِّي ‏ ‏أَحْنَفُ ‏ ‏تَصْطَكُّ ‏ ‏رُكْبَتَايَ فَقَالَ ‏ ‏ارْفَعْ ‏ ‏إِزَارَكَ ‏ ‏فَإِنَّ كُلَّ خَلْقِ اللَّهِ عَزَّ وَجَلَّ حَسَنٌ ‏ ‏فَمَا رُئِيَ ذَلِكَ الرَّجُلُ بَعْدُ إِلَّا ‏ ‏إِزَارُهُ ‏ ‏يُصِيبُ أَنْصَافَ سَاقَيْهِ ‏ ‏أَوْ إِلَى أَنْصَافِ سَاقَيْهِ ‏","","",""],[18657,18657,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الشَّرِيدِ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏أَوْ ‏ ‏يَعْقُوبَ بْنِ عَاصِمٍ ‏ ‏يَعْنِي ‏ ‏عَنِ ‏ ‏الشَّرِيدِ ‏ ‏كَذَا حَدَّثَنَاهُ أَبِي ‏ ‏قَالَ ‏ ‏أَرْدَفَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَلْفَهُ فَقَالَ ‏ ‏هَلْ مَعَكَ مِنْ شِعْرِ ‏ ‏أُمَيَّةَ ‏ ‏شَيْءٌ قُلْتُ نَعَمْ قَالَ أَنْشِدْنِي فَأَنْشَدْتُهُ بَيْتًا فَقَالَ ‏ ‏هِيهْ فَلَمْ يَزَلْ يَقُولُ ‏ ‏هِيهْ حَتَّى أَنْشَدْتُهُ مِائَةَ بَيْتٍ ‏","","",""],[18658,18658,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُسَيْنٍ الْمُعَلِّمِ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الشَّرِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الشَّرِيدِ بْنِ سُوَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَرْضٌ لَيْسَ لِأَحَدٍ فِيهَا شَرِيكٌ وَلَا قَسْمٌ إِلَّا الْجِوَارَ قَالَ ‏ ‏الْجَارُ أَحَقُّ ‏ ‏بِسَقَبِهِ ‏ ‏مَا كَانَ ‏","","",""],[18659,18659,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ ثَعْلَبَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏مُجَمِّعِ بْنِ جَارِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَقْتُلَنَّ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏الدَّجَّالَ ‏ ‏بِبَاب ‏ ‏لُدٍّ ‏ ‏أَوْ إِلَى جَانِبِ ‏ ‏لُدٍّ ‏","","",""],[18660,18660,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ حَدِيدٍ ‏ ‏عَنْ ‏ ‏صَخْرٍ الْغَامِدِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏ ‏قَالَ وَكَانَ إِذَا بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏أَوْ جَيْشًا ‏ ‏بَعَثَهُمْ مِنْ أَوَّلِ النَّهَارِ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏صَخْرٌ ‏ ‏رَجُلًا تَاجِرًا فَكَانَ ‏ ‏يَبْعَثُ تِجَارَتَهُ مِنْ أَوَّلِ النَّهَارِ قَالَ فَأَثْرَى وَكَثُرَ مَالُهُ ‏","","",""],[18661,18661,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ حَدِيدٍ ‏ ‏رَجُلًا مِنْ ‏ ‏بَجِيلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَخْرًا الْغَامِدِيَّ ‏ ‏رَجُلًا مِنْ ‏ ‏الْأَزْدِ ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏ ‏قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏بَعَثَهُمْ مِنْ أَوَّلِ النَّهَارِ ‏ ‏وَكَانَ ‏ ‏صَخْرٌ ‏ ‏رَجُلًا تَاجِرًا وَكَانَ لَهُ غِلْمَانٌ فَكَانَ ‏ ‏يَبْعَثُ غِلْمَانَهُ مِنْ أَوَّلِ النَّهَارِ قَالَ فَكَثُرَ مَالُهُ حَتَّى كَانَ لَا يَدْرِي أَيْنَ يَضَعُهُ ‏","","",""],[18662,18662,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ حَدِيدٍ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏صَخْرٍ الْغَامِدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏ ‏قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏بَعَثَهَا أَوَّلَ النَّهَارِ ‏ ‏وَكَانَ ‏ ‏صَخْرٌ ‏ ‏تَاجِرًا فَكَانَ ‏ ‏لَا يَبْعَثُ غِلْمَانَهُ إِلَّا مِنْ أَوَّلِ النَّهَارِ فَكَثُرَ مَالُهُ حَتَّى كَانَ لَا يَدْرِي أَيْنَ يَضَعُهُ ‏","","",""],[18663,18663,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ الْمَرْوَزِيُّ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُوسُفُ بْنُ يَعْقُوبَ الْمَاجِشُونُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَهُوَ يَمُوتُ فَقُلْتُ ‏ ‏أَقْرِئْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنِّي السَّلَامَ ‏","","",""],[18664,18664,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ثِقَةً ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏الْحَكَمُ ‏ ‏يَأْخُذُ عَنْهُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ ‏ ‏أَلْبَانِ الْإِبِلِ فَقَالَ تَوَضَّئُوا مِنْ أَلْبَانِهَا وَسُئِلَ عَنْ أَلْبَانِ الْغَنَمِ فَقَالَ لَا تَوَضَّئُوا مِنْ أَلْبَانِهَا ‏","","",""],[18665,18665,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏قَالَ ‏ ‏الْبَوْلُ عِنْدَنَا بِمَنْزِلَةِ الدَّمِ مَا لَمْ يَكُنْ قَدْرَ الدِّرْهَمِ فَلَا بَأْسَ بِهِ ‏","","",""],[18666,18666,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمُوتُ مُسْلِمٌ إِلَّا أَدْخَلَ اللَّهُ عَزَّ وَجَلَّ مَكَانَهُ النَّارَ يَهُودِيًّا أَوْ نَصْرَانِيًّا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏وَعَوْنِ بْنِ عُتْبَةَ ‏ ‏أَنَّهُمَا شَهِدَا ‏ ‏أَبَا بُرْدَةَ ‏ ‏يُحَدِّثُ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏قَالَ ‏ ‏عَوْنٌ ‏ ‏فَاسْتَحْلَفَهُ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ أَنَّ أَبَاهُ حَدَّثَهُ أَنَّهُ سَمِعَهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يُنْكِرْ ذَلِكَ ‏ ‏سَعِيدٌ ‏ ‏عَلَى ‏ ‏عَوْنٍ ‏ ‏أَنَّهُ اسْتَحْلَفَهُ ‏","","",""],[18667,18667,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏إِنَّ الْمَعْرُوفَ وَالْمُنْكَرَ ‏ ‏خَلِيقَتَانِ ‏ ‏يُنْصَبَانِ لِلنَّاسِ يَوْمَ الْقِيَامَةِ فَأَمَّا الْمَعْرُوفُ فَيُبَشِّرُ أَصْحَابَهُ وَيُوعِدُهُمْ الْخَيْرَ وَأَمَّا الْمُنْكَرُ فَيَقُولُ إِلَيْكُمْ إِلَيْكُمْ وَمَا يَسْتَطِيعُونَ لَهُ إِلَّا لُزُومًا ‏","","",""],[18668,18668,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً ثُمَّ قَالَ عَلَى مَكَانِكُمْ اثْبُتُوا ثُمَّ أَتَى الرِّجَالَ فَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَأْمُرُنِي أَنْ ‏ ‏آمُرَكُمْ أَنْ تَتَّقُوا اللَّهَ تَعَالَى وَأَنْ تَقُولُوا قَوْلًا سَدِيدًا ثُمَّ ‏ ‏تَخَلَّلَ ‏ ‏إِلَى النِّسَاءِ فَقَالَ لَهُنَّ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَأْمُرُنِي أَنْ آمُرَكُنَّ أَنْ تَتَّقُوا اللَّهَ وَأَنْ تَقُولُوا قَوْلًا سَدِيدًا قَالَ ثُمَّ رَجَعَ حَتَّى أَتَى الرِّجَالَ فَقَالَ إِذَا دَخَلْتُمْ مَسَاجِدَ الْمُسْلِمِينَ وَأَسْوَاقَهُمْ وَمَعَكُمْ النَّبْلُ فَخُذُوا ‏ ‏بِنُصُولِهَا ‏ ‏لَا تُصِيبُوا بِهَا أَحَدًا فَتُؤْذُوهُ أَوْ تَجْرَحُوهُ ‏","","",""],[18669,18669,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حِدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏قَالَ ‏ ‏حُدِّثْتُ ‏ ‏عَنِ ‏ ‏الْأَشْعَرِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَسْتَغْفِرُكَ لِمَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ إِنَّكَ أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏","","",""],[18670,18670,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏عُمَرُ ‏ ‏فِي وَصِيَّتِهِ ‏ ‏أَنْ لَا ‏ ‏يُقَرَّ ‏ ‏لِي عَامِلٌ أَكْثَرَ مِنْ سَنَةٍ ‏ ‏وَأَقِرُّوا ‏ ‏الْأَشْعَرِيَّ يَعْنِي أَبَا مُوسَى ‏ ‏أَرْبَعَ سِنِينَ ‏","","",""],[18671,18671,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا مَرَّتْ بِكُمْ جِنَازَةُ يَهُودِيٍّ أَوْ نَصْرَانِيٍّ أَوْ مُسْلِمٍ فَقُومُوا لَهَا فَلَسْتُمْ لَهَا تَقُومُونَ إِنَّمَا تَقُومُونَ لِمَنْ مَعَهَا مِنْ الْمَلَائِكَةِ ‏","","",""],[18672,18672,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏عَنِ ‏ ‏الْأَشْعَرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ ‏ ‏الْهَرْجَ ‏ ‏قَالُوا وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ قَالُوا أَكْثَرُ مِمَّا نَقْتُلُ إِنَّا لَنَقْتُلُ كُلَّ عَامٍ أَكْثَرَ مِنْ سَبْعِينَ أَلْفًا قَالَ إِنَّهُ لَيْسَ بِقَتْلِكُمْ الْمُشْرِكِينَ وَلَكِنْ قَتْلُ بَعْضِكُمْ بَعْضًا قَالُوا وَمَعَنَا عُقُولُنَا يَوْمَئِذٍ قَالَ إِنَّهُ لَتُنْزَعُ عُقُولُ أَهْلِ ذَلِكَ الزَّمَانِ وَيُخَلَّفُ لَهُ ‏ ‏هَبَاءٌ ‏ ‏مِنْ النَّاسِ يَحْسِبُ أَكْثَرُهُمْ أَنَّهُمْ عَلَى شَيْءٍ وَلَيْسُوا عَلَى شَيْءٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ مَا أَجِدُ لِي وَلَكُمْ مِنْهَا مَخْرَجًا إِنْ أَدْرَكَتْنِي وَإِيَّاكُمْ إِلَّا أَنْ نَخْرُجَ مِنْهَا كَمَا دَخَلْنَا فِيهَا لَمْ نُصِبْ مِنْهَا دَمًا وَلَا مَالًا ‏","","",""],[18673,18673,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18674,18674,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏لَقَدْ ذَكَّرَنَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏صَلَاةً كُنَّا ‏ ‏نُصَلِّيهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِمَّا نَسِينَاهَا وَإِمَّا تَرَكْنَاهَا عَمْدًا ‏ ‏يُكَبِّرُ كُلَّمَا رَكَعَ وَكُلَّمَا رَفَعَ وَكُلَّمَا سَجَدَ ‏","","",""],[18675,18675,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُقَالُ لَهُ ‏ ‏أَبُو عَبْدِ اللَّهِ ‏ ‏كَانَ يُجَالِسُ ‏ ‏جَعْفَرَ بْنَ رَبِيعَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بُرْدَةَ الْأَشْعَرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَعْظَمَ الذُّنُوبِ عِنْدَ اللَّهِ عَزَّ وَجَلَّ أَنْ يَلْقَاهُ عَبْدٌ بِهَا بَعْدَ الْكَبَائِرِ الَّتِي نَهَى عَنْهَا أَنْ يَمُوتَ الرَّجُلُ وَعَلَيْهِ دَيْنٌ لَا يَدَعُ ‏ ‏قَضَاءً ‏","","",""],[18676,18676,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ الرَّجُلُ يُحِبُّ الْقَوْمَ وَلَمَّا يَلْحَقْ بِهِمْ فَقَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏","","",""],[18677,18677,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَأَبُو مُوسَى ‏ ‏جَالِسَيْنِ وَهُمَا يَتَذَاكَرَانِ الْحَدِيثَ فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ أَيَّامٌ يُرْفَعُ فِيهَا الْعِلْمُ وَيَنْزِلُ فِيهَا الْجَهْلُ وَيَكْثُرُ فِيهَا الْهَرْجُ ‏ ‏وَالْهَرْجُ الْقَتْلُ ‏","","",""],[18678,18678,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنِ ‏ ‏الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏لَقَدْ ذَكَّرَنَا ‏ ‏ابْنُ أَبِي طَالِبٍ ‏ ‏وَنَحْنُ ‏ ‏بِالْبَصْرَةِ ‏ ‏صَلَاةً كُنَّا ‏ ‏نُصَلِّيهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُ إِذَا سَجَدَ وَإِذَا قَامَ ‏ ‏فَلَا أَدْرِي أَنَسِينَاهَا أَمْ تَرَكْنَاهَا عَمْدًا ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏وَثَابِتٍ ‏ ‏وَحُمَيْدٍ ‏ ‏وَحَبِيبٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ فَذَكَرَ نَحْوًا مِنْ حَدِيثِ ‏ ‏عَبْدِ الصَّمَدِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏إِلَّا أَنَّهُ قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ لَا أَجِدُ لِي وَلَكُمْ إِنْ أَدْرَكْتُهُنَّ إِلَّا أَنْ نَخْرُجَ مِنْهَا كَمَا دَخَلْنَاهَا لَمْ نُصِبْ فِيهَا دَمًا وَلَا مَالًا ‏","","",""],[18679,18679,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا مَرَرْتُمْ بِالسِّهَامِ فِي أَسْوَاقِ الْمُسْلِمِينَ أَوْ فِي مَسَاجِدِهِمْ فَأَمْسِكُوا ‏ ‏بِالْأَنْصَالِ ‏ ‏لَا تَجْرَحُوا بِهَا أَحَدًا ‏","","",""],[18680,18680,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَعِبَ ‏ ‏بِالْكِعَابِ ‏ ‏فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[18681,18681,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرِيرًا بِيَمِينِهِ وَذَهَبًا بِشِمَالِهِ فَقَالَ ‏ ‏أُحِلَّ لِإِنَاثِ أُمَّتِي وَحُرِّمَ عَلَى ذُكُورِهَا ‏","","",""],[18682,18682,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُحِلَّ الذَّهَبُ وَالْحَرِيرُ لِلْإِنَاثِ مِنْ أُمَّتِي وَحُرِّمَ عَلَى ذُكُورِهَا ‏","","",""],[18683,18683,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى الْأَشْعَرِيَّ ‏ ‏صَلَّى بِأَصْحَابِهِ صَلَاةً ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَنَا فَبَيَّنَ لَنَا سُنَّتَنَا وَعَلَّمَنَا صَلَاتَنَا فَقَالَ ‏ ‏إِذَا صَلَّيْتُمْ فَأَقِيمُوا صُفُوفَكُمْ ثُمَّ لِيَؤُمَّكُمْ أَحَدُكُمْ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[18684,18684,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَرْضِ قَوْمِي فَلَمَّا حَضَرَ الْحَجُّ حَجَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَجَجْتُ فَقَدِمْتُ عَلَيْهِ وَهُوَ نَازِلٌ ‏ ‏بِالْأَبْطَحِ ‏ ‏فَقَالَ لِي بِمَ ‏ ‏أَهْلَلْتَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏قَالَ قُلْتُ لَبَّيْكَ بِحَجٍّ كَحَجِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَحْسَنْتَ ثُمَّ قَالَ هَلْ سُقْتَ ‏ ‏هَدْيًا ‏ ‏فَقُلْتُ مَا فَعَلْتُ فَقَالَ لِي ‏ ‏اذْهَبْ فَطُفْ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ احْلِلْ فَانْطَلَقْتُ فَفَعَلْتُ مَا أَمَرَنِي وَأَتَيْتُ امْرَأَةً مِنْ قَوْمِي فَغَسَلَتْ رَأْسِي ‏ ‏بِالْخِطْمِيِّ ‏ ‏وَفَلَّتْهُ ثُمَّ ‏ ‏أَهْلَلْتُ ‏ ‏بِالْحَجِّ ‏ ‏يَوْمَ التَّرْوِيَةِ ‏ ‏فَمَا زِلْتُ ‏ ‏أُفْتِي النَّاسَ بِالَّذِي أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى تُوُفِّيَ ثُمَّ زَمَنَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏ثُمَّ زَمَنَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَبَيْنَا أَنَا قَائِمٌ عِنْدَ الْحَجَرِ الْأَسْوَدِ ‏ ‏أَوْ ‏ ‏الْمَقَامِ ‏ ‏أُفْتِ النَّاسَ بِالَّذِي أَمَرَنِي بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ أَتَانِي رَجُلٌ ‏ ‏فَسَارَّنِي ‏ ‏فَقَالَ لَا تَعْجَلْ بِفُتْيَاكَ فَإِنَّ أَمِيرَ الْمُؤْمِنِينَ قَدْ أَحْدَثَ فِي ‏ ‏الْمَنَاسِكِ ‏ ‏شَيْئًا فَقُلْتُ أَيُّهَا النَّاسُ مَنْ كُنَّا أَفْتَيْنَاهُ فِي ‏ ‏الْمَنَاسِكِ ‏ ‏شَيْئًا ‏ ‏فَلْيَتَّئِدْ ‏ ‏فَإِنَّ أَمِيرَ الْمُؤْمِنِينَ قَادِمٌ فَبِهِ فَأْتَمُّوا قَالَ فَقَدِمَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ هَلْ أَحْدَثْتَ فِي ‏ ‏الْمَنَاسِكِ ‏ ‏شَيْئًا قَالَ نَعَمْ أَنْ نَأْخُذَ بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ فَإِنَّهُ يَأْمُرُ بِالتَّمَامِ وَأَنْ نَأْخُذَ بِسُنَّةِ نَبِيِّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّهُ لَمْ يَحْلِلْ حَتَّى نَحَرَ ‏ ‏الْهَدْيَ ‏","","",""],[18685,18685,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَرْمَلَةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَمَانَانِ كَانَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُفِعَ أَحَدُهُمَا وَبَقِيَ الْآخَرُ ‏ { ‏وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ ‏}","","",""],[18686,18686,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي الْعُمَرِيَّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُحِلَّ لِإِنَاثِ أُمَّتِي الْحَرِيرُ وَالذَّهَبُ وَحُرِّمَ عَلَى ذُكُورِهَا ‏","","",""],[18687,18687,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَدِمَ رَجُلَانِ مَعِي مِنْ قَوْمِي قَالَ فَأَتَيْنَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَطَبَا وَتَكَلَّمَا فَجَعَلَا يُعَرِّضَانِ بِالْعَمَلِ فَتَغَيَّرَ وَجْهُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ رُئِيَ فِي وَجْهِهِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَخْوَنَكُمْ عِنْدِي مَنْ يَطْلُبُهُ فَعَلَيْكُمْ بِتَقْوَى اللَّهِ عَزَّ وَجَلَّ قَالَ فَمَا اسْتَعَانَ بِهِمَا عَلَى شَيْءٍ ‏","","",""],[18688,18688,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَسِبْتُهُ قَالَ فِي حَائِطٍ ‏ ‏فَجَاءَ رَجُلٌ فَسَلَّمَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبْ فَأْذَنْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ فَذَهَبْتُ فَإِذَا هُوَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقُلْتُ ادْخُلْ وَأَبْشِرْ بِالْجَنَّةِ فَمَا زَالَ يَحْمَدُ اللَّهَ عَزَّ وَجَلَّ حَتَّى جَلَسَ ثُمَّ جَاءَ آخَرُ فَسَلَّمَ فَقَالَ ائْذَنْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ فَانْطَلَقْتُ فَإِذَا هُوَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقُلْتُ ادْخُلْ وَأَبْشِرْ بِالْجَنَّةِ فَمَا زَالَ يَحْمَدُ اللَّهَ عَزَّ وَجَلَّ حَتَّى جَلَسَ ثُمَّ جَاءَ آخَرُ فَسَلَّمَ فَقَالَ اذْهَبْ فَأْذَنْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ عَلَى بَلْوَى شَدِيدَةٍ قَالَ فَانْطَلَقْتُ فَإِذَا هُوَ ‏ ‏عُثْمَانُ ‏ ‏فَقُلْتُ ادْخُلْ وَأَبْشِرْ بِالْجَنَّةِ عَلَى بَلْوَى شَدِيدَةٍ قَالَ فَجَعَلَ يَقُولُ اللَّهُمَّ صَبْرًا حَتَّى جَلَسَ ‏","","",""],[18689,18689,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَلَّمَ ‏ ‏عَبْدُ اللَّهِ بْنُ قَيْسٍ أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏عَلَى ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمْ ‏ ‏ثَلَاثَ مَرَّاتٍ فَلَمْ يُؤْذَنْ لَهُ ‏ ‏فَرَجَعَ فَأَرْسَلَ ‏ ‏عُمَرُ ‏ ‏فِي أَثَرِهِ لِمَ رَجَعْتَ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا سَلَّمَ أَحَدُكُمْ ثَلَاثًا فَلَمْ يُجَبْ فَلْيَرْجِعْ ‏","","",""],[18690,18690,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الْإِمَامُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ يَسْمَعْ اللَّهُ عَزَّ وَجَلَّ لَكُمْ فَإِنَّ اللَّهَ تَعَالَى قَضَى عَلَى لِسَانِ نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ‏","","",""],[18691,18691,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْخَازِنَ الْأَمِينَ الَّذِي يُعْطِي مَا أُمِرَ بِهِ كَامِلًا مُوَفَّرًا طَيِّبَةً بِهِ نَفْسُهُ حَتَّى يَدْفَعَهُ إِلَى الَّذِي أُمِرَ لَهُ بِهِ أَحَدُ الْمُتَصَدِّقِينَ ‏","","",""],[18692,18692,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ الْحَنَفِيُّ ‏ ‏عَنْ ‏ ‏غُنَيْمِ بْنِ قَيْسٍ ‏ ‏عَنِ ‏ ‏الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ عَيْنٍ زَانِيَةٌ ‏","","",""],[18693,18693,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ بُرْقَانَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏اخْتَصَمَ رَجُلَانِ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَرْضٍ أَحَدُهُمَا مِنْ أَهْلِ ‏ ‏حَضْرَمَوْتَ ‏ ‏قَالَ فَجَعَلَ يَمِينَ أَحَدِهِمَا قَالَ ‏ ‏فَضَجَّ ‏ ‏الْآخَرُ وَقَالَ إِنَّهُ إِذًا يَذْهَبُ بِأَرْضِي فَقَالَ ‏ ‏إِنْ هُوَ اقْتَطَعَهَا بِيَمِينِهِ ظُلْمًا كَانَ مِمَّنْ لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ يَوْمَ الْقِيَامَةِ وَلَا ‏ ‏يُزَكِّيهِ وَلَهُ عَذَابٌ أَلِيمٌ ‏ ‏قَالَ ‏ ‏وَوَرِعَ ‏ ‏الْآخَرُ فَرَدَّهَا ‏","","",""],[18694,18694,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَرِيرُ وَالذَّهَبُ حَرَامٌ عَلَى ذُكُورِ أُمَّتِي وَحِلٌّ لِإِنَاثِهِمْ ‏","","",""],[18695,18695,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسْتَأْمَرُ ‏ ‏الْيَتِيمَةُ فِي نَفْسِهَا فَإِنْ سَكَتَتْ فَقَدْ أَذِنَتْ وَإِنْ أَبَتْ لَمْ تُكْرَهْ ‏","","",""],[18696,18696,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَطْعِمُوا الْجَائِعَ وَفُكُّوا ‏ ‏الْعَانِيَ ‏ ‏وَعُودُوا الْمَرِيضَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏الْمَرْضَى ‏","","",""],[18697,18697,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نِكَاحَ إِلَّا ‏ ‏بِوَلِيٍّ ‏","","",""],[18698,18698,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ دَجَاجًا ‏","","",""],[18699,18699,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ يَعْنِي الْأَحْوَلَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَأَشْرَفْنَا عَلَى وَادٍ فَذَكَرَ مِنْ هَوْلِهِ فَجَعَلَ النَّاسُ يُكَبِّرُونَ وَيُهَلِّلُونَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏ارْبَعُوا ‏ ‏عَلَى أَنْفُسِكُمْ وَرَفَعُوا أَصْوَاتَهُمْ فَقَالَ أَيُّهَا النَّاسُ إِنَّكُمْ لَا تَدْعُونَ أَصَمَّ وَلَا غَائِبًا إِنَّهُ مَعَكُمْ ‏","","",""],[18700,18700,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَعِبَ ‏ ‏بِالنَّرْدِ ‏ ‏فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[18701,18701,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلٍ ‏ ‏فِيمَا أَعْلَمُ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَعِبَ ‏ ‏بِالنَّرْدِ ‏ ‏فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[18702,18702,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏مُرَّةَ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَلَ مِنْ الرِّجَالِ كَثِيرٌ وَلَمْ يَكْمُلْ مِنْ النِّسَاءِ إِلَّا ‏ ‏آسِيَةُ امْرَأَةُ فِرْعَوْنَ ‏ ‏وَمَرْيَمُ بِنْتُ عِمْرَانَ ‏ ‏وَإِنَّ فَضْلَ ‏ ‏عَائِشَةَ ‏ ‏عَلَى النِّسَاءِ كَفَضْلِ ‏ ‏الثَّرِيدِ ‏ ‏عَلَى سَائِرِ الطَّعَامِ ‏","","",""],[18703,18703,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْمَسْعُودِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ ‏ ‏أَسْمَاءَ ‏ ‏لَمَّا قَدِمَتْ لَقِيَهَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فِي بَعْضِ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏آلْحَبَشِيَّةُ هِيَ قَالَتْ نَعَمْ فَقَالَ نِعْمَ الْقَوْمُ أَنْتُمْ لَوْلَا أَنَّكُمْ سَبَقْتُمْ بِالْهِجْرَةِ فَقَالَتْ هِيَ ‏ ‏لِعُمَرَ ‏ ‏كُنْتُمْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْمِلُ ‏ ‏رَاجِلَكُمْ ‏ ‏وَيُعَلِّمُ جَاهِلَكُمْ وَفَرَرْنَا بِدِينِنَا أَمَا إِنِّي لَا أَرْجِعُ حَتَّى أَذْكُرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَجَعَتْ إِلَيْهِ فَقَالَتْ لَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ لَكُمْ الْهِجْرَةُ مَرَّتَيْنِ هِجْرَتُكُمْ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏وَهِجْرَتُكُمْ إِلَى ‏ ‏الْحَبَشَةِ ‏","","",""],[18704,18704,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْمَسْعُودِيِّ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏سَمَّى لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْسَهُ أَسْمَاءً مِنْهَا مَا حَفِظْنَا فَقَالَ ‏ ‏أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَأَحْمَدُ ‏ ‏وَالْمُقَفِّي ‏ ‏وَالْحَاشِرُ ‏ ‏وَنَبِيُّ الرَّحْمَةِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَنَبِيُّ التَّوْبَةِ ‏ ‏وَنَبِيُّ الْمَلْحَمَةِ ‏","","",""],[18705,18705,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ رَجُلٌ أَحَبَّ قَوْمًا وَلَمَّا يَلْحَقْ بِهِمْ قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏","","",""],[18706,18706,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَحَدَ أَصْبَرُ عَلَى أَذًى يَسْمَعُهُ مِنْ اللَّهِ عَزَّ وَجَلَّ إِنَّهُ يُشْرَكُ بِهِ وَهُوَ يَرْزُقُهُمْ ‏","","",""],[18707,18707,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَاءُ أُمَّتِي بِالطَّعْنِ وَالطَّاعُونِ فَقِيلَ يَا رَسُولَ اللَّهِ هَذَا الطَّعْنُ قَدْ عَرَفْنَاهُ فَمَا الطَّاعُونُ قَالَ وَخْزُ أَعْدَائِكُمْ مِنْ الْجِنِّ وَفِي كُلٍّ شُهَدَاءُ ‏","","",""],[18708,18708,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ تَعَالَى يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا ‏","","",""],[18709,18709,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَرْبَعٍ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَنَامُ وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ يَخْفِضُ ‏ ‏الْقِسْطَ ‏ ‏وَيَرْفَعُهُ يُرْفَعُ إِلَيْهِ عَمَلُ اللَّيْلِ بِالنَّهَارِ وَعَمَلُ النَّهَارِ بِاللَّيْلِ ‏","","",""],[18710,18710,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَى كُلِّ مُسْلِمٍ صَدَقَةٌ قَالَ أَفَرَأَيْتَ إِنْ لَمْ يَجِدْ قَالَ يَعْمَلُ بِيَدِهِ فَيَنْفَعُ نَفْسَهُ وَيَتَصَدَّقُ قَالَ أَفَرَأَيْتَ إِنْ لَمْ يَسْتَطِعْ أَنْ يَفْعَلَ قَالَ يُعِينُ ذَا الْحَاجَةِ ‏ ‏الْمَلْهُوفَ ‏ ‏قَالَ أَرَأَيْتَ إِنْ لَمْ يَفْعَلْ قَالَ يَأْمُرُ بِالْخَيْرِ أَوْ بِالْعَدْلِ قَالَ أَفَرَأَيْتَ إِنْ لَمْ يَسْتَطِعْ أَنْ يَفْعَلَ قَالَ يُمْسِكُ عَنْ الشَّرِّ فَإِنَّهُ لَهُ ‏ ‏صَدَقَةٌ ‏","","",""],[18711,18711,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏صَالِحٍ الثَّوْرِيِّ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَتْ لَهُ أَمَةٌ فَعَلَّمَهَا فَأَحْسَنَ تَعْلِيمَهَا وَأَدَّبَهَا فَأَحْسَنَ تَأْدِيبَهَا وَأَعْتَقَهَا فَتَزَوَّجَهَا فَلَهُ أَجْرَانِ وَعَبْدٌ أَدَّى حَقَّ اللَّهِ عَزَّ وَجَلَّ وَحَقَّ ‏ ‏مَوَالِيهِ ‏ ‏وَرَجُلٌ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏آمَنَ بِمَا جَاءَ بِهِ ‏ ‏عِيسَى ‏ ‏وَمَا جَاءَ بِهِ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَهُ أَجْرَانِ ‏","","",""],[18712,18712,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏","","",""],[18713,18713,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏مُنِيخٌ ‏ ‏بِالْأَبْطَحِ ‏ ‏فَقَالَ لِي أَحَجَجْتَ قُلْتُ نَعَمْ قَالَ فَبِمَ ‏ ‏أَهْلَلْتَ ‏ ‏قَالَ قُلْتُ لَبَّيْكَ ‏ ‏بِإِهْلَالٍ ‏ ‏كَإِهْلَالِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَدْ أَحْسَنْتَ قَالَ ‏ ‏طُفْ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ ‏ ‏أَحِلَّ ‏ ‏قَالَ ‏ ‏فَطُفْتُ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ أَتَيْتُ امْرَأَةً مِنْ ‏ ‏بَنِي قَيْسٍ ‏ ‏فَفَلَّتْ رَأْسِي ثُمَّ أَهْلَلْتُ بِالْحَجِّ قَالَ فَكُنْتُ أُفْتِي بِهِ النَّاسَ حَتَّى كَانَ خِلَافَةُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ رَجُلٌ يَا ‏ ‏أَبَا مُوسَى ‏ ‏أَوْ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏رُوَيْدَكَ بَعْضَ فُتْيَاكَ فَإِنَّكَ لَا تَدْرِي مَا أَحْدَثَ أَمِيرُ الْمُؤْمِنِينَ فِي شَأْنِ ‏ ‏النُّسُكِ ‏ ‏بَعْدَكَ قَالَ فَقَالَ يَا أَيُّهَا النَّاسُ مَنْ كُنَّا أَفْتَيْنَاهُ فُتْيَا ‏ ‏فَلْيَتَّئِدْ ‏ ‏فَإِنَّ أَمِيرَ الْمُؤْمِنِينَ قَادِمٌ عَلَيْكُمْ فَبِهِ ‏ ‏فَأْتَمُّوا ‏ ‏قَالَ فَقَدِمَ ‏ ‏عُمَرُ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ إِنْ نَأْخُذْ بِكِتَابِ اللَّهِ فَإِنَّ كِتَابَ اللَّهِ تَعَالَى يَأْمُرُنَا بِالتَّمَامِ وَإِنْ نَأْخُذْ بِسُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ ‏ ‏يَحِلَّ ‏ ‏حَتَّى بَلَغَ ‏ ‏الْهَدْيُ ‏ ‏مَحِلَّهُ ‏","","",""],[18714,18714,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّهُ أُغْمِيَ عَلَيْهِ فَبَكَتْ عَلَيْهِ أُمُّ وَلَدِهِ فَلَمَّا أَفَاقَ قَالَ لَهَا أَمَا بَلَغَكِ مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَسَأَلْتُهَا فَقَالَتْ ‏ ‏لَيْسَ مِنَّا مَنْ ‏ ‏سَلَقَ ‏ ‏وَحَلَقَ ‏ ‏وَخَرَقَ ‏","","",""],[18715,18715,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَمِعَ بِي مِنْ أُمَّتِي أَوْ يَهُودِيٌّ أَوْ نَصْرَانِيٌّ فَلَمْ يُؤْمِنْ بِي لَمْ يَدْخُلْ الْجَنَّةَ ‏","","",""],[18716,18716,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏أَسْوَدُ طَوِيلٌ ‏ ‏قَالَ ‏ ‏جَعَلَ ‏ ‏أَبُو التَّيَّاحِ ‏ ‏يَنْعَتُهُ ‏ ‏أَنَّهُ ‏ ‏قَدِمَ مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏الْبَصْرَةَ ‏ ‏فَكَتَبَ إِلَى ‏ ‏أَبِي مُوسَى ‏ ‏فَكَتَبَ إِلَيْهِ ‏ ‏أَبُو مُوسَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَمْشِي فَمَالَ إِلَى ‏ ‏دَمْثٍ ‏ ‏فِي جَنْبِ حَائِطٍ فَبَالَ ثُمَّ قَالَ كَانَ ‏ ‏بَنَو إِسْرَائِيلَ ‏ ‏إِذَا بَالَ أَحَدُهُمْ فَأَصَابَهُ شَيْءٌ مِنْ بَوْلِهِ يَتْبَعُهُ فَقَرَضَهُ ‏ ‏بِالْمَقَارِيضِ ‏ ‏وَقَالَ ‏ ‏إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَبُولَ ‏ ‏فَلْيَرْتَدْ ‏ ‏لِبَوْلِهِ ‏","","",""],[18717,18717,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏وَهُوَ بِحَضْرَةِ الْعَدُوِّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَبْوَابَ الْجَنَّةِ تَحْتَ ظِلَالِ السُّيُوفِ ‏ ‏قَالَ ‏ ‏فَقَامَ رَجُلٌ مِنْ الْقَوْمِ ‏ ‏رَثُّ ‏ ‏الْهَيْئَةِ فَقَالَ يَا ‏ ‏أَبَا مُوسَى ‏ ‏آنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏فَرَجَعَ إِلَى أَصْحَابِهِ ‏ ‏فَقَالَ ‏ ‏أَقْرَأُ عَلَيْكُمْ السَّلَامَ ثُمَّ كَسَرَ ‏ ‏جَفْنَ ‏ ‏سَيْفِهِ ‏ ‏فَأَلْقَاهُ ثُمَّ مَشَى بِسَيْفِهِ فَضَرَبَ بِهِ حَتَّى قُتِلَ ‏","","",""],[18718,18718,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏أُغْمِيَ عَلَى ‏ ‏أَبِي مُوسَى ‏ ‏فَبَكَوْا عَلَيْهِ فَقَالَ ‏ ‏إِنِّي بَرِيءٌ مِمَّنْ بَرِئَ مِنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلُوا عَنْ ذَلِكَ امْرَأَتَهُ فَقَالَتْ مَنْ ‏ ‏حَلَقَ ‏ ‏أَوْ ‏ ‏خَرَقَ ‏ ‏أَوْ ‏ ‏سَلَقَ ‏","","",""],[18719,18719,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْأَحْدَبِ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏قَالَ ‏ ‏أُغْمِيَ عَلَى ‏ ‏أَبِي مُوسَى ‏ ‏فَبَكَوْا عَلَيْهِ فَأَفَاقَ فَقَالَ ‏ ‏إِنِّي أَبْرَأُ إِلَيْكُمْ مِمَّنْ بَرِئَ مِنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّنْ ‏ ‏حَلَقَ ‏ ‏أَوْ ‏ ‏خَرَقَ ‏ ‏أَوْ ‏ ‏سَلَقَ ‏","","",""],[18720,18720,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏وَحَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ مِخْرَاقٍ ‏ ‏عَنْ ‏ ‏أَبِي كِنَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَابِ بَيْتٍ فِيهِ ‏ ‏نَفَرٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَ وَأَخَذَ ‏ ‏بِعِضَادَتَيْ ‏ ‏الْبَابِ ثُمَّ قَالَ هَلْ فِي الْبَيْتِ إِلَّا قُرَشِيٌّ قَالَ فَقِيلَ يَا رَسُولَ اللَّهِ غَيْرُ فُلَانٍ ابْنِ أُخْتِنَا فَقَالَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ قَالَ ثُمَّ قَالَ إِنَّ هَذَا الْأَمْرَ فِي ‏ ‏قُرَيْشٍ ‏ ‏مَا دَامُوا إِذَا اسْتُرْحِمُوا رَحِمُوا وَإِذَا حَكَمُوا عَدَلُوا وَإِذَا قَسَمُوا أَقْسَطُوا فَمَنْ لَمْ يَفْعَلْ ذَلِكَ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يُقْبَلُ مِنْهُ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏","","",""],[18721,18721,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏أَبِي مُوسَى ‏ ‏وَعَبْدِ اللَّهِ ‏ ‏فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏أَلَمْ تَسْمَعْ لِقَوْلِ ‏ ‏عَمَّارٍ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَأَجْنَبْتُ فَلَمْ أَجِدْ الْمَاءَ فَتَمَرَّغْتُ فِي ‏ ‏الصَّعِيدِ ‏ ‏كَمَا تَمَرَّغُ الدَّابَّةُ ثُمَّ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ ‏ ‏إِنَّمَا كَانَ يَكْفِيكَ أَنْ تَقُولَ وَضَرَبَ بِيَدِهِ عَلَى الْأَرْضِ ثُمَّ مَسَحَ كُلَّ وَاحِدَةٍ مِنْهُمَا بِصَاحِبَتِهَا ثُمَّ مَسَحَ بِهِمَا ‏ ‏وَجْهَهُ ‏ ‏لَمْ يُجِزْ ‏ ‏الْأَعْمَشُ ‏ ‏الْكَفَّيْنِ ‏","","",""],[18722,18722,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ الرَّجُلَ يُقَاتِلُ شَجَاعَةً وَيُقَاتِلُ ‏ ‏حَمِيَّةً ‏ ‏وَيُقَاتِلُ ‏ ‏رِيَاءً ‏ ‏فَأَيُّ ذَلِكَ فِي سَبِيلِ اللَّهِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ عَزَّ وَجَلَّ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18723,18723,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏مُعَاذًا ‏ ‏وَأَبَا مُوسَى ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَأَمَرَهُمَا أَنْ يُعَلِّمَا النَّاسَ الْقُرْآنَ ‏","","",""],[18724,18724,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏بُرَيْدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏إِذَا مَرَّ أَحَدُكُمْ بِالنَّبْلِ فِي مَسَاجِدِنَا أَوْ أَسْوَاقِنَا فَلْيُمْسِكْ بِيَدِهِ عَلَى ‏ ‏مَشَاقِصِهَا ‏ ‏لَا ‏ ‏يَعْقِرْ ‏ ‏أَحَدًا ‏","","",""],[18725,18725,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏بُرَيْدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏تَعَاهَدُوا هَذَا الْقُرْآنَ ‏ ‏فَوَالَّذِي ‏ ‏نَفْسِي بِيَدِهِ لَهُوَ أَشَدُّ ‏ ‏تَفَلُّتًا ‏ ‏مِنْ أَحَدِكُمْ مِنْ الْإِبِلِ مِنْ ‏ ‏عُقُلِهِ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏قُلْتُ ‏ ‏لِبُرَيْدٍ ‏ ‏هَذِهِ الْأَحَادِيثُ الَّتِي حَدَّثْتَنِي عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هِيَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ لَا أَقُولُ لَكَ ‏","","",""],[18726,18726,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ التَّيْمِيُّ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏الْفُضَيْلِ بْنِ مَيْسَرَةَ ‏ ‏حَدِيثَ ‏ ‏أَبِي حَرِيزٍ ‏ ‏أَنَّ ‏ ‏أَبَا بُرْدَةَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏أَوْصَى ‏ ‏أَبُو مُوسَى ‏ ‏حِينَ حَضَرَهُ الْمَوْتُ فَقَالَ ‏ ‏إِذَا انْطَلَقْتُمْ بِجِنَازَتِي فَأَسْرِعُوا الْمَشْيَ وَلَا يَتَّبِعُنِي ‏ ‏مُجَمَّرٌ ‏ ‏وَلَا تَجْعَلُوا فِي لَحْدِي شَيْئًا يَحُولُ بَيْنِي وَبَيْنَ التُّرَابِ وَلَا تَجْعَلُوا عَلَى قَبْرِي بِنَاءً وَأُشْهِدُكُمْ أَنَّنِي بَرِيءٌ مِنْ كُلِّ ‏ ‏حَالِقَةٍ ‏ ‏أَوْ ‏ ‏سَالِقَةٍ ‏ ‏أَوْ ‏ ‏خَارِقَةٍ ‏ ‏قَالُوا أَوَسَمِعْتَ فِيهِ شَيْئًا قَالَ نَعَمْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18727,18727,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏فَقَالَ بِمَ أَهْلَلْتَ فَقُلْتُ بِإِهْلَالٍ كَإِهْلَالِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَلْ سُقْتَ مِنْ ‏ ‏هَدْيٍ ‏ ‏قُلْتُ لَا قَالَ ‏ ‏طُفْ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ حِلَّ ‏","","",""],[18728,18728,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى الْأَشْعَرِيَّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ مَثَلُ ‏ ‏الْأُتْرُجَّةِ ‏ ‏طَعْمُهَا طَيِّبٌ وَرِيحُهَا طَيِّبٌ وَمَثَلُ الْمُؤْمِنِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ التَّمْرَةِ طَعْمُهَا طَيِّبٌ وَلَا رِيحَ لَهَا وَمَثَلُ الْفَاجِرِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الرَّيْحَانَةِ مُرٌّ طَعْمُهَا وَرِيحُهَا طَيِّبٌ وَمَثَلُ الْفَاجِرِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ ‏ ‏الْحَنْظَلَةِ ‏ ‏مُرٌّ طَعْمُهَا وَلَا رِيحَ لَهَا ‏","","",""],[18729,18729,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏غَالِبٍ التَّمَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَسْرُوقَ بْنَ أَوْسٍ ‏ ‏أَوْ ‏ ‏أَوْسَ بْنَ مَسْرُوقٍ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي يَرْبُوعٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا مُوسَى الْأَشْعَرِيَّ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَصَابِعُ سَوَاءٌ ‏ ‏فَقُلْتُ ‏ ‏لِغَالِبٍ ‏ ‏عَشْرٌ عَشْرٌ ‏ ‏فَقَالَ ‏ ‏نَعَمْ ‏","","",""],[18730,18730,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ مَيْسَرَةَ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَعِبَ ‏ ‏بِالنَّرْدِ ‏ ‏فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[18731,18731,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا غَيَّرَتْ النَّارُ لَوْنَهُ ‏","","",""],[18732,18732,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَحْرُسُهُ أَصْحَابُهُ ‏ ‏وَذَكَرَ الْحَدِيثَ ‏","","",""],[18733,18733,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏زَهْدَمٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّهُ ‏ ‏جَاءَ رَجُلٌ وَهُوَ يَأْكُلُ دَجَاجًا فَتَنَحَّى فَقَالَ إِنِّي حَلَفْتُ أَنْ لَا آكُلَهُ إِنِّي رَأَيْتُهُ يَأْكُلُ شَيْئًا قَذِرًا فَقَالَ ادْنُهُ فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُهُ ‏","","",""],[18734,18734,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قِيلَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلُ يُحِبُّ الْقَوْمَ وَلَمَّا يَلْحَقْ بِهِمْ قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏","","",""],[18735,18735,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏طَلْحَةُ بْنُ يَحْيَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِيَسْتَأْذِنْ أَحَدُكُمْ ثَلَاثًا فَإِنْ أُذِنَ لَهُ وَإِلَّا فَلْيَرْجِعْ ‏","","",""],[18736,18736,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏غَالِبٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ مَسْرُوقٍ ‏ ‏أَوْ ‏ ‏مَسْرُوقِ بْنِ أَوْسٍ الْيَرْبُوعِيِّ ‏ ‏مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَصَابِعُ سَوَاءٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْتُ لَهُ عَشْرًا عَشْرًا ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[18737,18737,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏غَيْلَانُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏رَهْطٍ ‏ ‏مِنْ ‏ ‏الْأَشْعَرِيِّينَ ‏ ‏نَسْتَحْمِلُهُ ‏ ‏فَقَالَ لَا وَاللَّهِ مَا أَحْمِلُكُمْ وَمَا عِنْدِي مَا أَحْمِلُكُمْ عَلَيْهِ فَلَبِثْنَا مَا شَاءَ اللَّهُ ثُمَّ أَمَرَ لَنَا بِثَلَاثِ ‏ ‏ذَوْدٍ ‏ ‏غُرِّ الذُّرَى ‏ ‏فَلَمَّا انْطَلَقْنَا قَالَ بَعْضُنَا لِبَعْضٍ أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَسْتَحْمِلُهُ ‏ ‏فَحَلَفَ أَنْ لَا يَحْمِلَنَا ارْجِعُوا بِنَا أَيْ حَتَّى نُذَكِّرَهُ قَالَ فَأَتَيْنَاهُ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّا أَتَيْنَاكَ ‏ ‏نَسْتَحْمِلُكَ ‏ ‏فَحَلَفْتَ أَنْ لَا تَحْمِلَنَا ثُمَّ حَمَلْتَنَا فَقَالَ مَا أَنَا حَمَلْتُكُمْ بَلْ اللَّهُ عَزَّ وَجَلَّ حَمَلَكُمْ إِنِّي وَاللَّهِ إِنْ شَاءَ اللَّهُ تَعَالَى ‏ ‏لَا أَحْلِفُ عَلَى يَمِينٍ فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا إِلَّا أَتَيْتُ الَّذِي هُوَ خَيْرٌ وَكَفَّرْتُ عَنْ يَمِينِي ‏ ‏أَوْ قَالَ إِلَّا كَفَّرْتُ يَمِينِي ‏ ‏وَأَتَيْتُ الَّذِي هُوَ خَيْرٌ ‏","","",""],[18738,18738,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ أَعْيَنَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَفِظَ مَا بَيْنَ ‏ ‏فُقْمَيْهِ ‏ ‏وَفَرْجَهُ دَخَلَ الْجَنَّةَ ‏","","",""],[18739,18739,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏عَوْنًا ‏ ‏وَسَعِيدَ بْنَ أَبِي بُرْدَةَ ‏ ‏حَدَّثَاهُ أَنَّهُمَا شَهِدَا ‏ ‏أَبَا بُرْدَةَ ‏ ‏يُحَدِّثُ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمُوتُ رَجُلٌ مُسْلِمٌ إِلَّا أَدْخَلَ اللَّهُ عَزَّ وَجَلَّ مَكَانَهُ النَّارَ يَهُودِيًّا أَوْ نَصْرَانِيًّا ‏ ‏قَالَ ‏ ‏فَاسْتَحْلَفَهُ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ ثَلَاثَ مَرَّاتٍ أَنَّ أَبَاهُ حَدَّثَهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَحَلَفَ لَهُ ‏ ‏قَالَ ‏ ‏فَلَمْ يُحَدِّثْنِي ‏ ‏سَعِيدٌ ‏ ‏أَنَّهُ اسْتَحْلَفَهُ وَلَمْ يُنْكِرْ عَلَى ‏ ‏عَوْنٍ ‏ ‏قَوْلَهُ ‏","","",""],[18740,18740,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏غَالِبٍ التَّمَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَوْسَ بْنَ مَسْرُوقٍ ‏ ‏رَجُلًا مِنَّا كَانَ أَخَذَ الدِّرْهَمَيْنِ عَلَى عَهْدِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏وَغَزَا فِي خِلَافَتِهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَصَابِعُ سَوَاءٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ عَشْرٌ عَشْرٌ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[18741,18741,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو بِشْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَمِعَ بِي مِنْ أُمَّتِي أَوْ يَهُودِيٌّ أَوْ نَصْرَانِيٌّ ثُمَّ لَمْ يُؤْمِنْ بِي دَخَلَ النَّارَ ‏","","",""],[18742,18742,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرِ بْنَ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُكْثِرُ زِيَارَةَ ‏ ‏الْأَنْصَارِ ‏ ‏خَاصَّةً وَعَامَّةً فَكَانَ إِذَا زَارَ خَاصَّةً أَتَى الرَّجُلَ فِي مَنْزِلِهِ وَإِذَا زَارَ عَامَّةً أَتَى الْمَسْجِدَ ‏","","",""],[18743,18743,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ جَارِيَةٌ فَأَعْتَقَهَا وَتَزَوَّجَهَا كَانَ لَهُ أَجْرَانِ ‏","","",""],[18744,18744,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ عَمِلَ حَسَنَةً فَسُرَّ بِهَا وَعَمِلَ سَيِّئَةً فَسَاءَتْهُ فَهُوَ مُؤْمِنٌ ‏","","",""],[18745,18745,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏مُجَمِّعِ بْنِ يَحْيَى بْنِ زَيْدِ بْنِ جَارِيَةَ الْأَنْصَارِيِّ ‏ ‏قَالَ سَمِعْتُهُ يَذْكُرُهُ عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏صَلَّيْنَا الْمَغْرِبَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قُلْنَا لَوْ انْتَظَرْنَا حَتَّى نُصَلِّيَ مَعَهُ الْعِشَاءَ قَالَ فَانْتَظَرْنَا فَخَرَجَ إِلَيْنَا فَقَالَ مَا زِلْتُمْ هَاهُنَا قُلْنَا نَعَمْ يَا رَسُولَ اللَّهِ قُلْنَا نُصَلِّي مَعَكَ الْعِشَاءَ قَالَ أَحْسَنْتُمْ ‏ ‏أَوْ أَصَبْتُمْ ‏ ‏ثُمَّ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ قَالَ وَكَانَ كَثِيرًا مَا يَرْفَعُ رَأْسَهُ إِلَى السَّمَاءِ فَقَالَ ‏ ‏النُّجُومُ أَمَنَةٌ لِلسَّمَاءِ فَإِذَا ذَهَبَتْ النُّجُومُ أَتَى السَّمَاءَ مَا تُوعَدُ وَأَنَا أَمَنَةٌ لِأَصْحَابِي فَإِذَا ذَهَبْتُ أَتَى أَصْحَابِي مَا يُوعَدُونَ وَأَصْحَابِي أَمَنَةٌ لِأُمَّتِي فَإِذَا ذَهَبَتْ أَصْحَابِي أَتَى أُمَّتِي مَا يُوعَدُونَ ‏","","",""],[18746,18746,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ الْعَزِيزِ الْأُرْدُنِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُعَيْمٍ الْقَيْسِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَرْزَبٍ الْأَشْعَرِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏حَدَّثَهُمْ قَالَ ‏ ‏لَمَّا هَزَمَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏هَوَازِنَ ‏ ‏بِحُنَيْنٍ ‏ ‏عَقَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَبِي عَامِرٍ الْأَشْعَرِيِّ ‏ ‏عَلَى خَيْلِ الطَّلَبِ فَطَلَبَ فَكُنْتُ فِيمَنْ طَلَبَهُمْ فَأَسْرَعَ بِهِ فَرَسُهُ فَأَدْرَكَ ‏ ‏ابْنَ دُرَيْدِ بْنِ الصِّمَّةِ ‏ ‏فَقَتَلَ ‏ ‏أَبَا عَامِرٍ ‏ ‏وَأَخَذَ اللِّوَاءَ وَشَدَدْتُ عَلَى ‏ ‏ابْنِ دُرَيْدٍ ‏ ‏فَقَتَلْتُهُ وَأَخَذْتُ اللِّوَاءَ وَانْصَرَفْتُ بِالنَّاسِ فَلَمَّا رَآنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْمِلُ اللِّوَاءَ قَالَ يَا ‏ ‏أَبَا مُوسَى ‏ ‏قُتِلَ ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ قُلْتُ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَفَعَ يَدَيْهِ يَدْعُو يَقُولُ ‏ ‏اللَّهُمَّ ‏ ‏عُبَيْدَكَ ‏ ‏عُبَيْدًا أَبَا عَامِرٍ ‏ ‏اجْعَلْهُ مِنْ الْأَكْثَرِينَ يَوْمَ الْقِيَامَةِ ‏","","",""],[18747,18747,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏شَيْخٍ لَهُمْ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏مَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏دَمْثٍ ‏ ‏إِلَى جَنْبِ حَائِطٍ فَبَالَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لِأَبِى التَّيَّاحِ ‏ ‏جَالِسًا قَالَ لَا أَدْرِي ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانُوا إِذَا أَصَابَهُمْ الْبَوْلُ ‏ ‏قَرَضُوهُ ‏ ‏بِالْمَقَارِيضِ ‏ ‏فَإِذَا بَالَ أَحَدُكُمْ ‏ ‏فَلْيَرْتَدْ ‏ ‏لِبَوْلِهِ ‏","","",""],[18748,18748,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏الْفُضَيْلِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏أَبِي حَرِيزٍ ‏ ‏أَنَّ ‏ ‏أَبَا بُرْدَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏حَدِيثِ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ لَا يَدْخُلُونَ الْجَنَّةَ مُدْمِنُ خَمْرٍ وَقَاطِعُ رَحِمٍ وَمُصَدِّقٌ بِالسِّحْرِ وَمَنْ مَاتَ مُدْمِنًا لِلْخَمْرِ سَقَاهُ اللَّهُ عَزَّ وَجَلَّ مِنْ نَهْرِ ‏ ‏الْغُوطَةِ ‏ ‏قِيلَ وَمَا نَهْرُ ‏ ‏الْغُوطَةِ ‏ ‏قَالَ نَهْرٌ يَجْرِي مِنْ فُرُوجِ ‏ ‏الْمُومِسَاتِ ‏ ‏يُؤْذِي أَهْلَ النَّارِ رِيحُ فُرُوجِهِمْ ‏","","",""],[18749,18749,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏وُلِدَ لِي غُلَامٌ فَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمَّاهُ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَحَنَّكَهُ ‏ ‏بِتَمْرَةٍ ‏","","",""],[18750,18750,"","","‏ ‏وَقَالَ ‏ ‏احْتَرَقَ بَيْتٌ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَلَى أَهْلِهِ فَحُدِّثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَأْنِهِمْ فَقَالَ ‏ ‏إِنَّمَا هَذِهِ النَّارُ عَدُوٌّ لَكُمْ فَإِذَا نِمْتُمْ فَأَطْفِئُوهَا عَنْكُمْ ‏","","",""],[18751,18751,"","","‏ ‏قَالَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَعَثَ أَحَدًا مِنْ أَصْحَابِهِ فِي بَعْضِ أَمْرِهِ قَالَ ‏ ‏بَشِّرُوا وَلَا ‏ ‏تُنَفِّرُوا ‏ ‏وَيَسِّرُوا وَلَا تُعَسِّرُوا ‏","","",""],[18752,18752,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مَثَلَ مَا بَعَثَنِي اللَّهُ عَزَّ وَجَلَّ بِهِ مِنْ الْهُدَى وَالْعِلْمِ كَمَثَلِ ‏ ‏غَيْثٍ ‏ ‏أَصَابَ الْأَرْضَ فَكَانَتْ مِنْهُ طَائِفَةٌ قَبِلَتْ فَأَنْبَتَتْ ‏ ‏الْكَلَأَ ‏ ‏وَالْعُشْبَ الْكَثِيرَ وَكَانَتْ مِنْهَا ‏ ‏أَجَادِبُ ‏ ‏أَمْسَكَتْ الْمَاءَ فَنَفَعَ اللَّهُ عَزَّ وَجَلَّ بِهَا نَاسًا فَشَرِبُوا فَرَعَوْا وَسَقَوْا وَزَرَعُوا وَأَسْقَوْا وَأَصَابَتْ طَائِفَةً مِنْهَا أُخْرَى إِنَّمَا هِيَ ‏ ‏قِيعَانٌ ‏ ‏لَا تُمْسِكُ مَاءً وَلَا تُنْبِتُ ‏ ‏كَلَأً ‏ ‏فَذَلِكَ مَثَلُ مَنْ فَقُهَ فِي دِينِ اللَّهِ عَزَّ وَجَلَّ وَنَفَعَهُ اللَّهُ عَزَّ وَجَلَّ بِمَا بَعَثَنِي بِهِ وَنَفَعَ بِهِ فَعَلِمَ وَعَلَّمَ وَمَثَلُ مَنْ لَمْ يَرْفَعْ بِذَلِكَ رَأْسًا وَلَمْ يَقْبَلْ هُدَى اللَّهِ عَزَّ وَجَلَّ الَّذِي أُرْسِلْتُ بِهِ ‏","","",""],[18753,18753,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَضُوءٍ فَتَوَضَّأَ وَصَلَّى وَقَالَ ‏ ‏اللَّهُمَّ أَصْلِحْ لِي دِينِي وَوَسِّعْ عَلَيَّ فِي ذَاتِي وَبَارِكْ لِي فِي رِزْقِي ‏","","",""],[18754,18754,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏وَعَلِيِّ بْنِ زَيْدٍ ‏ ‏وَالْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ قَالَ وَمَا هُوَ قَالَ ‏ ‏لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[18755,18755,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ ثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْمَةُ دُرَّةٌ مُجَوَّفَةٌ طُولُهَا فِي السَّمَاءِ سِتُّونَ مِيلًا فِي كُلِّ زَاوِيَةٍ مِنْهَا لِلْمُؤْمِنِ أَهْلٌ لَا يَرَاهُمْ الْآخَرُونَ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏عَفَّانُ ‏ ‏لِكُلِّ زَاوِيَةٍ ‏","","",""],[18756,18756,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا مَرَّ أَحَدُكُمْ فِي مَسْجِدٍ أَوْ سُوقٍ أَوْ مَجْلِسٍ وَبِيَدِهِ نِبَالٌ فَلْيَأْخُذْ ‏ ‏بِنِصَالِهَا ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏فَوَاللَّهِ مَا مِتْنَا حَتَّى سَدَّدَهَا بَعْضُنَا فِي وُجُوهِ بَعْضٍ ‏","","",""],[18757,18757,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ يَعْنِي ابْنَ عُمَارَةَ ‏ ‏عَنْ ‏ ‏غُنَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَعْطَرَتْ الْمَرْأَةُ فَخَرَجَتْ عَلَى الْقَوْمِ لِيَجِدُوا رِيحَهَا فَهِيَ كَذَا وَكَذَا ‏","","",""],[18758,18758,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَلْ أَدُلُّكُمْ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ ‏ ‏أَوَمَا تَدْرِي مَا كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ ‏ ‏قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[18759,18759,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏وَثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَعِبَ ‏ ‏بِالنَّرْدِ ‏ ‏فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[18760,18760,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى هُوَ ابْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏اسْتَأْذَنَ عَلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏ثَلَاثَ مَرَّاتٍ فَلَمْ يُؤْذَنْ لَهُ فَرَجَعَ فَقَالَ أَلَمْ أَسْمَعْ صَوْتَ ‏ ‏عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏آنِفًا ‏ ‏قَالُوا بَلَى قَالَ فَاطْلُبُوهُ قَالَ فَطَلَبُوهُ فَدُعِيَ فَقَالَ مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ ‏ ‏اسْتَأْذَنْتُ ثَلَاثًا فَلَمْ يُؤْذَنْ لِي فَرَجَعْتُ كُنَّا نُؤْمَرُ بِهَذَا فَقَالَ لَتَأْتِيَنَّ عَلَيْهِ ‏ ‏بِالْبَيِّنَةِ ‏ ‏أَوْ لَأَفْعَلَنَّ قَالَ فَأَتَى مَسْجِدًا ‏ ‏أَوْ مَجْلِسًا ‏ ‏لِلْأَنْصَارِ ‏ ‏فَقَالُوا لَا يَشْهَدُ لَكَ إِلَّا أَصْغَرُنَا فَقَامَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَشَهِدَ لَهُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏خَفِيَ هَذَا عَلَيَّ مِنْ أَمْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلْهَانِي عَنْهُ ‏ ‏الصَّفْقُ ‏ ‏بِالْأَسْوَاقِ ‏","","",""],[18761,18761,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَسَامَةُ بْنُ زُهَيْرٍ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏قَسَامَةَ بْنِ زُهَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ ‏ ‏آدَمَ ‏ ‏مِنْ قَبْضَةٍ قَبَضَهَا مِنْ جَمِيعِ الْأَرْضِ فَجَاءَ بَنُو ‏ ‏آدَمَ ‏ ‏عَلَى قَدْرِ الْأَرْضِ جَاءَ مِنْهُمْ الْأَبْيَضُ وَالْأَحْمَرُ وَالْأَسْوَدُ وَبَيْنَ ذَلِكَ وَالْخَبِيثُ وَالطَّيِّبُ وَالسَّهْلُ ‏ ‏وَالْحَزْنُ ‏ ‏وَبَيْنَ ذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏قَسَامَةَ بْنِ زُهَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَشْعَرِيَّ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18762,18762,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏بُرَيْدُ بْنُ أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّهُ سَأَلَهُ سَائِلٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْفَعُوا تُؤْجَرُوا وَلْيَقْضِ اللَّهُ عَزَّ وَجَلَّ عَلَى لِسَانِ نَبِيِّهِ مَا أَحَبَّ ‏","","",""],[18763,18763,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏لَقَدْ ذَكَّرَنَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏صَلَاةً صَلَّيْنَاهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِمَّا أَنْ نَكُونَ نَسِينَاهَا وَإِمَّا أَنْ نَكُونَ تَرَكْنَاهَا عَمْدًا ‏ ‏يُكَبِّرُ كُلَّمَا رَكَعَ وَإِذَا سَجَدَ وَإِذَا رَفَعَ ‏","","",""],[18764,18764,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ دَيْلَمٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏الْيَهُودُ ‏ ‏يَتَعَاطَسُونَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَاءَ أَنْ يَقُولَ لَهُمْ يَرْحَمُكُمْ اللَّهُ فَكَانَ يَقُولُ لَهُمْ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏","","",""],[18765,18765,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَنَامُ وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ يَخْفِضُ ‏ ‏الْقِسْطَ ‏ ‏وَيَرْفَعُهُ حِجَابُهُ النَّارُ لَوْ كَشَفَهَا لَأَحْرَقَتْ ‏ ‏سُبُحَاتُ ‏ ‏وَجْهِهِ كُلَّ شَيْءٍ أَدْرَكَهُ بَصَرُهُ ثُمَّ قَرَأَ ‏ ‏أَبُو عُبَيْدَةَ ‏ { ‏نُودِيَ أَنْ بُورِكَ مَنْ فِي النَّارِ وَمَنْ حَوْلَهَا وَسُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[18766,18766,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏أَرَى أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏مِنْ أَهْلِ الْبَيْتِ ‏ ‏أَوْ مَا ذَكَرَ مِنْ هَذَا ‏","","",""],[18767,18767,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَحَدٌ أَصْبَرَ عَلَى أَذًى يَسْمَعُهُ مِنْ اللَّهِ عَزَّ وَجَلَّ يَدْعُونَ لَهُ وَلَدًا ‏ ‏وَيُعَافِيهِمْ وَيَرْزُقُهُمْ ‏","","",""],[18768,18768,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ أَخًا ‏ ‏لِأَبِي مُوسَى ‏ ‏كَانَ يَتَسَرَّعُ فِي ‏ ‏الْفِتْنَةِ ‏ ‏فَجَعَلَ ‏ ‏يَنْهَاهُ وَلَا يَنْتَهِي فَقَالَ إِنْ كُنْتُ أَرَى أَنَّهُ ‏ ‏سَيَكْفِيكَ مِنِّي الْيَسِيرُ ‏ ‏أَوْ قَالَ مِنْ الْمَوْعِظَةِ ‏ ‏دُونَ مَا أَرَى وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَاجَهَ الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَقَتَلَ أَحَدُهُمَا الْآخَرَ فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ قَالُوا يَا رَسُولَ اللَّهِ هَذَا الْقَاتِلُ فَمَا بَالُ الْمَقْتُولِ قَالَ إِنَّهُ أَرَادَ قَتْلَ صَاحِبِهِ ‏","","",""],[18769,18769,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏أَبِي مُوسَى ‏ ‏فَقَدَّمَ فِي طَعَامِهِ لَحْمَ دَجَاجٍ وَفِي الْقَوْمِ رَجُلٌ مِنْ ‏ ‏بَنِي تَيْمِ اللَّهِ ‏ ‏أَحْمَرُ كَأَنَّهُ ‏ ‏مَوْلًى ‏ ‏فَلَمْ ‏ ‏يَدْنُ ‏ ‏قَالَ لَهُ ‏ ‏أَبُو مُوسَى ‏ ‏ادْنُ ‏ ‏فَإِنِّي قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ مِنْهُ قَالَ إِنِّي رَأَيْتُهُ يَأْكُلُ شَيْئًا فَقَذِرْتُهُ فَحَلَفْتُ أَنْ لَا أَطْعَمَهُ أَبَدًا فَقَالَ ‏ ‏ادْنُ ‏ ‏أُخْبِرْكَ عَنْ ذَلِكَ إِنِّي أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏رَهْطٍ ‏ ‏مِنْ ‏ ‏الْأَشْعَرِيِّينَ ‏ ‏نَسْتَحْمِلُهُ ‏ ‏وَهُوَ يَقْسِمُ نَعَمًا مِنْ نَعَمْ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏أَحْسِبُهُ وَهُوَ غَضْبَانُ ‏ ‏فَقَالَ لَا وَاللَّهِ مَا أَحْمِلُكُمْ وَمَا عِنْدِي مَا أَحْمِلُكُمْ فَانْطَلَقْنَا فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَهْبِ ‏ ‏إِبِلٍ فَقَالَ أَيْنَ هَؤُلَاءِ ‏ ‏الْأَشْعَرِيُّونَ ‏ ‏فَأَتَيْنَا فَأَمَرَ لَنَا بِخَمْسِ ‏ ‏ذَوْدٍ ‏ ‏غُرِّ الذُّرَى ‏ ‏فَانْدَفَعْنَا فَقُلْتُ لِأَصْحَابِي أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَسْتَحْمِلُهُ ‏ ‏فَحَلَفَ أَنْ لَا يَحْمِلَنَا ثُمَّ أَرْسَلَ إِلَيْنَا فَحَمَلَنَا فَقُلْتُ نَسِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمِينَهُ وَاللَّهِ لَئِنْ تَغَفَّلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمِينَهُ لَا نُفْلِحُ أَبَدًا ارْجِعُوا بِنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْنُذَكِّرْهُ يَمِينَهُ فَرَجَعْنَا إِلَيْهِ فَقُلْنَا يَا رَسُولَ اللَّهِ أَتَيْنَاكَ ‏ ‏نَسْتَحْمِلُكَ ‏ ‏فَحَلَفْتَ أَنْ لَا تَحْمِلَنَا ثُمَّ حَمَلْتَنَا فَعَرَفْنَا ‏ ‏أَوْ ظَنَنَّا ‏ ‏أَنَّكَ نَسِيتَ يَمِينَكَ فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْطَلِقُوا فَإِنَّمَا حَمَلَكُمْ اللَّهُ عَزَّ وَجَلَّ وَإِنِّي وَاللَّهِ إِنْ شَاءَ اللَّهُ لَا أَحْلِفُ عَلَى يَمِينٍ فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا إِلَّا أَتَيْتُ الَّذِي هُوَ خَيْرٌ ‏ ‏وَتَحَلَّلْتُهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏أَبِي مُوسَى ‏ ‏فَقُرِّبَ لَهُ طَعَامٌ فِيهِ دَجَاجٌ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو قِلَابَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي تَيْمِ اللَّهِ ‏ ‏يُقَالُ لَهُ ‏ ‏زَهْدَمٌ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏أَبِي مُوسَى ‏ ‏فَأُتِيَ بِلَحْمِ دَجَاجٍ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏وَعَنْ ‏ ‏الْقَاسِمِ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏قَالَ ‏ ‏كَانَ بَيْنَنَا وَبَيْنَ ‏ ‏الْأَشْعَرِيِّ ‏ ‏إِخَاءٌ ‏ ‏فَذَكَرَ الْحَدِيثَ وَمَعْنَاهُ ‏","","",""],[18770,18770,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏عَلَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَنَا وَسُنَّتَنَا فَقَالَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا قَالَ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ يُجِبْكُمْ اللَّهُ تَعَالَى وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا رَفَعَ فَارْفَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ يَسْمَعْ اللَّهُ لَكُمْ وَإِذَا سَجَدَ فَاسْجُدُوا وَإِذَا رَفَعَ فَارْفَعُوا فَإِنَّ الْإِمَامَ يَسْجُدُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتِلْكَ بِتِلْكَ ‏","","",""],[18771,18771,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏أَنَّ أَعْرَابِيًّا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ الرَّجُلُ يُقَاتِلُ لِلْمَغْنَمِ وَالرَّجُلُ يُقَاتِلُ لِيُذْكَرَ وَالرَّجُلُ يُقَاتِلُ لِيُرَى مَكَانُهُ فَمَنْ فِي سَبِيلِ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18772,18772,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعِي نَفَرٌ مِنْ قَوْمِي فَقَالَ أَبْشِرُوا وَبَشِّرُوا مَنْ وَرَاءَكُمْ إِنَّهُ ‏ ‏مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ صَادِقًا بِهَا دَخَلَ الْجَنَّةَ فَخَرَجْنَا مِنْ عِنْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُبَشِّرُ النَّاسَ فَاسْتَقْبَلَنَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَرَجَعَ بِنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ إِذَنْ يَتَّكِلَ النَّاسُ قَالَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18773,18773,"","","‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ سَلَّامٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَجْلَحُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ بِهَا أَشْرِبَةً فَمَا أَشْرَبُ وَمَا أَدَعُ قَالَ وَمَا هِيَ قُلْتُ ‏ ‏الْبِتْعُ ‏ ‏وَالْمِزْرُ ‏ ‏فَلَمْ يَدْرِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا هُوَ فَقَالَ مَا ‏ ‏الْبِتْعُ ‏ ‏وَمَا ‏ ‏الْمِزْرُ ‏ ‏قَالَ أَمَّا ‏ ‏الْبِتْعُ ‏ ‏فَنَبِيذُ الذُّرَةِ يُطْبَخُ حَتَّى يَعُودَ ‏ ‏بِتْعًا ‏ ‏وَأَمَّا ‏ ‏الْمِزْرُ ‏ ‏فَنَبِيذُ الْعَسَلِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَشْرَبَنَّ مُسْكِرًا ‏","","",""],[18774,18774,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ الثَّقَفِيُّ أَبُو مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ فَجَعَلْنَا لَا نَصْعَدُ ‏ ‏شَرَفًا ‏ ‏وَلَا نَعْلُو ‏ ‏شَرَفًا ‏ ‏وَلَا نَهْبِطُ فِي وَادٍ إِلَّا رَفَعْنَا أَصْوَاتَنَا بِالتَّكْبِيرِ قَالَ فَدَنَا مِنَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيُّهَا النَّاسُ ‏ ‏ارْبَعُوا ‏ ‏عَلَى أَنْفُسِكُمْ فَإِنَّكُمْ مَا تَدْعُونَ أَصَمَّ وَلَا غَائِبًا إِنَّمَا تَدْعُونَ سَمِيعًا بَصِيرًا إِنَّ الَّذِي تَدْعُونَ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ عُنُقِ رَاحِلَتِهِ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏أَلَا أُعَلِّمُكَ كَلِمَةً مِنْ كُنُوزِ الْجَنَّةِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[18775,18775,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ وَهُوَ النَّضْرُ بْنُ إِسْمَاعِيلَ يَعْنِي الْقَاصَّ ‏ ‏حَدَّثَنَا ‏ ‏بُرَيْدٌ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ الْقِيَامَةِ لَمْ يَبْقَ مُؤْمِنٌ إِلَّا أُتِيَ بِيَهُودِيٍّ أَوْ نَصْرَانِيٍّ حَتَّى يُدْفَعَ إِلَيْهِ يُقَالُ لَهُ هَذَا فِدَاؤُكَ مِنْ النَّارِ قَالَ ‏ ‏أَبُو بُرْدَةَ ‏ ‏فَاسْتَحْلَفَنِي ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ أَسَمِعْتَ ‏ ‏أَبَا مُوسَى ‏ ‏يَذْكُرُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ نَعَمْ فَسُرَّ بِذَلِكَ ‏ ‏عُمَرُ ‏","","",""],[18776,18776,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُنَفِّلُ ‏ ‏فِي مَغَازِيهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏أَنَّهُ كَانَ يُنَفِّلُ فِي مَغَازِيهِ ‏","","",""],[18777,18777,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ يُؤْتَوْنَ أُجُورَهُمْ مَرَّتَيْنِ رَجُلٌ كَانَتْ لَهُ أَمَةٌ فَأَدَّبَهَا فَأَحْسَنَ تَأْدِيبَهَا وَعَلَّمَهَا فَأَحْسَنَ تَعْلِيمَهَا ثُمَّ أَعْتَقَهَا فَتَزَوَّجَهَا وَمَمْلُوكٌ أَعْطَى حَقَّ رَبِّهِ عَزَّ وَجَلَّ وَحَقَّ ‏ ‏مَوَالِيهِ ‏ ‏وَرَجُلٌ آمَنَ بِكِتَابِهِ ‏ ‏وَبِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لِي ‏ ‏الشَّعْبِيُّ ‏ ‏خُذْهَا بِغَيْرِ شَيْءٍ وَلَوْ سِرْتَ فِيهَا إِلَى ‏ ‏كَرْمَانَ ‏ ‏لَكَانَ ذَلِكَ يَسِيرًا ‏","","",""],[18778,18778,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏رَجُلَيْنِ اخْتَصَمَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي دَابَّةٍ لَيْسَ لِوَاحِدٍ مِنْهُمَا ‏ ‏بَيِّنَةٌ ‏ ‏فَجَعَلَهُ بَيْنَهُمَا نِصْفَيْنِ ‏","","",""],[18779,18779,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَدْرِي ‏ ‏أَوْ هَلْ أَدُلُّكَ عَلَى ‏ ‏كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ قَالَ اللَّهُ ‏ ‏وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[18780,18780,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّهُمْ كَانُوا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَرَفَعُوا أَصْوَاتَهُمْ بِالدُّعَاءِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ لَا تَدْعُونَ أَصَمَّ وَلَا غَائِبًا إِنَّكُمْ تَدْعُونَ قَرِيبًا مُجِيبًا يَسْمَعُ دُعَاءَكُمْ وَيَسْتَجِيبُ ثُمَّ قَالَ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏أَوْ يَا ‏ ‏أَبَا مُوسَى ‏ ‏أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[18781,18781,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ يَعْنِي ابْنَ أَبِي سُلَيْمَانَ الْعَزْرَمِيَّ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي كَاهِلٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ اتَّقُوا هَذَا الشِّرْكَ فَإِنَّهُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ فَقَامَ إِلَيْهِ ‏ ‏عَبْدُ اللَّهِ بْنُ حَزْنٍ ‏ ‏وَقَيْسُ بْنُ المُضَارِبِ ‏ ‏فَقَالَا وَاللَّهِ لَتَخْرُجَنَّ مِمَّا قُلْتَ أَوْ لَنَأْتِيَنَّ ‏ ‏عُمَرَ ‏ ‏مَأْذُونٌ لَنَا أَوْ غَيْرُ مَأْذُونٍ قَالَ بَلْ أَخْرُجُ مِمَّا قُلْتُ خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَقَالَ أَيُّهَا النَّاسُ اتَّقُوا هَذَا الشِّرْكَ فَإِنَّهُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ فَقَالَ لَهُ مَنْ شَاءَ اللَّهُ أَنْ يَقُولَ وَكَيْفَ ‏ ‏نَتَّقِيهِ وَهُوَ أَخْفَى مِنْ دَبِيبِ النَّمْلِ يَا رَسُولَ اللَّهِ قَالَ قُولُوا ‏ ‏اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نُشْرِكَ بِكَ شَيْئًا نَعْلَمُهُ وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُ ‏","","",""],[18782,18782,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَرْمَلَةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي أَيُّوبَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَمَانَانِ كَانَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُفِعَ أَحَدُهُمَا وَبَقِيَ الْآخَرُ ‏ { ‏وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ ‏}","","",""],[18783,18783,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏حِطَّانَ بْنَ عَبْدِ اللَّهِ الرَّقَاشِيَّ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏قُلْتُ لِصَاحِبٍ لِي تَعَالَ فَلْنَجْعَلْ يَوْمَنَا هَذَا لِلَّهِ عَزَّ وَجَلَّ فَلَكَأَنَّمَا شَهِدَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏وَمِنْهُمْ مَنْ يَقُولُ تَعَالَ فَلْنَجْعَلْ يَوْمَنَا هَذَا لِلَّهِ عَزَّ وَجَلَّ فَمَا زَالَ يُرَدِّدُهَا حَتَّى تَمَنَّيْتُ أَنْ ‏ ‏أَسِيخَ ‏ ‏فِي الْأَرْضِ ‏","","",""],[18784,18784,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى الْأَشْعَرِيَّ ‏ ‏كَانَ لَهُ أَخٌ يُقَالُ لَهُ ‏ ‏أَبُو رُهْمٍ ‏ ‏وَكَانَ يَتَسَرَّعُ فِي ‏ ‏الْفِتْنَةِ ‏ ‏وَكَانَ ‏ ‏الْأَشْعَرِيُّ ‏ ‏يَكْرَهُ ‏ ‏الْفِتْنَةَ ‏ ‏فَقَالَ لَهُ لَوْلَا مَا أَبْلَغْتَ إِلَيَّ مَا حَدَّثْتُكَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمَيْنِ الْتَقَيَا بِسَيْفَيْهِمَا فَقَتَلَ أَحَدُهُمَا الْآخَرَ إِلَّا دَخَلَا جَمِيعًا النَّارَ ‏","","",""],[18785,18785,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏غَالِبٍ التَّمَّارِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقِ بْنِ أَوْسٍ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏حَدَّثَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى فِي الْأَصَابِعِ عَشْرًا عَشْرًا مِنْ الْإِبِلِ ‏","","",""],[18786,18786,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏أَبَا مُوسَى ‏ ‏اسْتَأْذَنَ عَلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏قَالَ وَاحِدَةً ثِنْتَيْنِ ثَلَاثَ ثُمَّ رَجَعَ ‏ ‏أَبُو مُوسَى ‏ ‏فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏لَتَأْتِيَنَّ عَلَى هَذَا ‏ ‏بِبَيِّنَةٍ ‏ ‏أَوْ لَأَفْعَلَنَّ ‏ ‏قَالَ كَأَنَّهُ يَقُولُ أَجْعَلُكَ ‏ ‏نَكَالًا ‏ ‏فِي الْآفَاقِ ‏ ‏فَانْطَلَقَ ‏ ‏أَبُو مُوسَى ‏ ‏إِلَى مَجْلِسٍ فِيهِ ‏ ‏الْأَنْصَارُ ‏ ‏فَذَكَرَ ذَلِكَ لَهُمْ فَقَالَ أَلَمْ تَعْلَمُوا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَأْذَنَ أَحَدُكُمْ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ قَالُوا بَلَى لَا يَقُومُ مَعَكَ إِلَّا أَصْغَرُنَا قَالَ فَقَامَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏فَقَالَ هَذَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَخَلَّى عَنْهُ ‏","","",""],[18787,18787,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏لَيْثٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏يُحَدِّثُ عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏إِنَّ أُنَاسًا مَرُّوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ يُسْرِعُونَ بِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِتَكُونَ عَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏","","",""],[18788,18788,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الرَّازِيُّ ‏ ‏عَن ‏ ‏الرَّبِيعِ بْنِ أَنَسٍ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مُوسَى ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْبَلُ اللَّهُ عَزَّ وَجَلَّ صَلَاةَ رَجُلٍ فِي جَسَدِهِ شَيْءٌ مِنْ ‏ ‏الْخَلُوقِ ‏","","",""],[18789,18789,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا ثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى الْأَشْعَرِيَّ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ ‏ ‏الْأُتْرُجَّةِ ‏ ‏طَعْمُهَا طَيِّبٌ وَرِيحُهَا طَيِّبٌ وَمَثَلُ الْمُؤْمِنِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ التَّمْرَةِ طَعْمُهَا طَيِّبٌ وَلَا رِيحَ لَهَا وَمَثَلُ الْفَاجِرِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الرَّيْحَانَةِ رِيحُهَا طَيِّبٌ وَطَعْمُهَا مُرٌّ وَمَثَلُ الْفَاجِرِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ ‏ ‏الْحَنْظَلَةِ ‏ ‏طَعْمُهَا مُرٌّ وَلَا رِيحَ لَهَا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏بِهَذَيْنِ كِلَيْهِمَا ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏أَنَسٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَن ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[18790,18790,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏مَنْصُورٍ ‏ ‏عَن ‏ ‏إِبْرَاهِيمَ ‏ ‏عَن ‏ ‏يَزِيدَ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏أُغْمِيَ عَلَى ‏ ‏أَبِي مُوسَى ‏ ‏فَبَكَوْا عَلَيْهِ فَقَالَ إِنِّي بَرِيءٌ مِمَّنْ ‏ ‏بَرِئَ مِنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلُوا عَنْ ذَلِكَ امْرَأَتَهُ مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ أَمَا عَلِمْتُمْ مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ مِمَّنْ ‏ ‏حَلَقَ ‏ ‏وَسَلَقَ ‏ ‏وَخَرَقَ ‏","","",""],[18791,18791,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏عَوْفٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَالِدًا الْأَحْدَبَ ‏ ‏عَن ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏قَالَ ‏ ‏أُغْمِيَ عَلَى ‏ ‏أَبِي مُوسَى ‏ ‏فَبَكَوْا عَلَيْهِ فَأَفَاقَ فَقَالَ ‏ ‏إِنِّي أَبْرَأُ إِلَيْكُمْ مِمَّا بَرِئَ مِنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّنْ ‏ ‏حَلَقَ ‏ ‏وَسَلَقَ ‏ ‏وَخَرَقَ ‏ ‏وَحَدَّثَنَا ‏ ‏بِهِمَا ‏ ‏عَفَّانُ ‏ ‏مَرَّةً أُخْرَى فَقَالَ فِيهِمَا جَمِيعًا مِمَّنْ ‏ ‏حَلَقَ ‏ ‏أَوْ ‏ ‏سَلَقَ ‏ ‏أَوْ ‏ ‏خَرَقَ ‏","","",""],[18792,18792,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمٌ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَحْرُسُهُ أَصْحَابُهُ فَقُمْتُ ذَاتَ لَيْلَةٍ فَلَمْ أَرَهُ فِي مَنَامِهِ فَأَخَذَنِي مَا قَدُمَ وَمَا حَدَثَ فَذَهَبْتُ أَنْظُرُ فَإِذَا أَنَا ‏ ‏بِمُعَاذٍ ‏ ‏قَدْ لَقِيَ الَّذِي لَقِيتُ فَسَمِعْنَا صَوْتًا مِثْلَ ‏ ‏هَزِيزِ الرَّحَا فَوَقَفَا عَلَى مَكَانِهِمَا فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ قِبَلِ الصَّوْتِ فَقَالَ هَلْ تَدْرُونَ أَيْنَ كُنْتُ وَفِيمَ كُنْتُ ‏ ‏أَتَانِي آتٍ مِنْ رَبِّي عَزَّ وَجَلَّ فَخَيَّرَنِي بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ وَبَيْنَ ‏ ‏الشَّفَاعَةِ ‏ ‏فَاخْتَرْتُ ‏ ‏الشَّفَاعَةَ ‏ ‏فَقَالَا يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ عَزَّ وَجَلَّ أَنْ يَجْعَلَنَا فِي ‏ ‏شَفَاعَتِكَ ‏ ‏فَقَالَ أَنْتُمْ وَمَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا فِي ‏ ‏شَفَاعَتِي ‏","","",""],[18793,18793,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَن ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ وَيَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا ‏","","",""],[18794,18794,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏غَالِبٌ التَّمَّارُ ‏ ‏عَن ‏ ‏مَسْرُوقِ بْنِ أَوْسٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْأَصَابِعِ عَشْرٌ عَشْرٌ ‏","","",""],[18795,18795,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونٍَ ‏ ‏أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَن ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَن ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏سَمَّى لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْسَهُ أَسْمَاءً مِنْهَا مَا حَفِظْنَا وَمِنْهَا مَا لَمْ نَحْفَظْ فَقَالَ ‏ ‏أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَأَنَا ‏ ‏أَحْمَدُ ‏ ‏والْمُقَفِّي ‏ ‏وَالْحَاشِرُ ‏ ‏وَنَبِيُّ التَّوْبَةِ ‏ ‏وَنَبِيُّ الْمَلْحَمَةِ ‏","","",""],[18796,18796,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَن ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَن ‏ ‏أَبِي السَّلِيلِ ‏ ‏عَن ‏ ‏زَهْدَمٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏انْطَلَقْنَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَسْتَحْمِلُهُ ‏ ‏فَقَالَ وَاللَّهِ لَا أَحْمِلُكُمْ فَرَجَعْنَا فَبَعَثَ إِلَيْنَا بِثَلَاثٍ ‏ ‏بُقْعِ ‏ ‏الذُّرَى ‏ ‏فَقَالَ بَعْضُنَا لِبَعْضٍ حَلَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ لَا يَحْمِلَنَا فَأَتَيْنَاهُ فَقُلْنَا إِنَّكَ حَلَفْتَ أَنْ لَا تَحْمِلَنَا فَقَالَ ‏ ‏مَا أَنَا حَمَلْتُكُمْ إِنَّمَا حَمَلَكُمْ اللَّهُ تَعَالَى مَا عَلَى الْأَرْضِ يَمِينٌ أَحْلِفُ عَلَيْهَا فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا إِلَّا أَتَيْتُهُ ‏","","",""],[18797,18797,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ الْكُوفِيُّ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏فَقَالَ ‏ ‏أَيْ بَنِيَّ أَلَا أُحَدِّثُكُمْ حَدِيثًا ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً أَعْتَقَ اللَّهُ عَزَّ وَجَلَّ بِكُلِّ عُضْوٍ مِنْهَا عُضْوًا مِنْهُ مِنْ النَّارِ ‏","","",""],[18798,18798,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَن ‏ ‏بُرَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏رِوَايَةً ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا وَمَثَلُ الْجَلِيسِ ‏ ‏الصَّالِحِ مَثَلُ الْعَطَّارِ إِنْ لَمْ يُحْذِكَ مِنْ عِطْرِهِ عَلَقَكَ مِنْ رِيحِهِ وَمَثَلُ الْجَلِيسِ السُّوءِ مَثَلُ ‏ ‏الْكِيرِ ‏ ‏إِنْ لَمْ يُحْرِقْكَ نَالَكَ مِنْ شَرَرِهِ وَالْخَازِنُ الْأَمِينُ الَّذِي يُؤَدِّي مَا أُمِرَ بِهِ مُؤْتَجِرًا أَحَدُ الْمُتَصَدِّقِينَ ‏","","",""],[18799,18799,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَن ‏ ‏بُرَيْدٍ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا ‏","","",""],[18800,18800,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَن ‏ ‏إِبْرَاهِيمَ ‏ ‏عَن ‏ ‏سَهْمِ بْنِ مِنْجَابٍ ‏ ‏عَن ‏ ‏الْقَرْثَعِ ‏ ‏قَالَ ‏ ‏لَمَّا ثَقُلَ ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏صَاحَتْ ‏ ‏امْرَأَتُهُ ‏ ‏فَقَالَ لَهَا أَمَا عَلِمْتِ مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ بَلَى ثُمَّ سَكَتَتْ فَلَمَّا مَاتَ قِيل لَهَا أَيُّ شَيْءٍ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ ‏ ‏مَنْ ‏ ‏حَلَقَ ‏ ‏أَوْ ‏ ‏خَرَقَ ‏ ‏أَوْ ‏ ‏سَلَقَ ‏","","",""]];
